// Generated by scripts/gen-sheet-model.mjs from designer_gui/sheet_model.json and properties.json. Do not edit.
export const PROPERTY_DESCRIPTIONS: Readonly<Record<string, string>> = {"ImageDataModel.imageData":"the image data","LanguageSQLDataModel.alias":"the alias on which the SQLs should be executed","LanguageSQLDataModel.statements":"the statements which should be executed when the keys are extracted","LinkInformationDataModel.tableName":"The table name that should be linked","LinkInformationDataModel.primaryKey":"The primary key of the table","LinkInformationDataModel.isUIDTable":"This will automatically insert a new UID in the primary key field, whenever a new dataset is created.","LinkInformationDataModel.readonly":"This will be a read only table","LinkInformationDataModel.foreignKey":"The foreign key","MailbridgeMailserverDataModel.enabled":"If true, this mailbridge will run.","MailbridgeMailserverDataModel.bridgeName":"The name can be set freely and is used to identify the mailbridge. It is recommended to use a name that describes which mailserver is used.","MailbridgeMailserverDataModel.serverName":"The alias name of one of your mailservers. The mailbridge will access the chosen mailserver.","MailbridgeMailserverDataModel.timeout":"Time interval, in milliseconds, after which the mailbridge stops trying to read from a mailbox.","MailbridgeMailserverDataModel.user":"The login of an ADITO user, who has their e-mail configurations set. The mailbridge will use the configured credentials of this user to authenticate at the mailserver.","MailbridgeMailserverDataModel.intervall":"The time intervall, in milliseconds, for the regular runs of the mailbridge.","MailbridgeMailserverDataModel.receivingFilter":"With these, filters you can add some extra processing to the mailbridge. Possible values are:\n\n* `CRLF`: Replaces are line breaks with \" \". This can be used to ensure correct processing, if emails are read that were created by Linux or macOS users, as these operating system either only use (Linux) or (macOS).\n* `Extractattachment`: Expects all incoming emails to only have one attachment and then uses the attachment to create the mail object.\n* `Extractattachment2`: Expects all incoming emails to only have one attachment that’s encoded in MIME type `Message/rfc822`. The mailbridge will extract the attachment and form the mail object based on the attachment.\n* `log`: Writes the email to the log.\n* `printtext`: Writes the email to the console logger.","MailbridgeMailserverDataModel.bridgeMode":"One of three modes:\n\n* `0` / `PROCESS`: only the mailbridge process is executed, the email is not copied to the mail repository.\n* `1` / `COPY`: the email is copied to the mail repository, no further processing is done.\n* `2` / `BOTH`: the actions of `PROCESS` and `COPY` are combined. The email gets copied into the mail repository and is then processed by the mailbridge process","MailbridgeMailserverDataModel.flagMode":"This determines which emails are loaded by the mailbridge.\n\n* `0` / `New`: Only fetches newly received emails, this does not include older unread emails\n* `1` / `Read`: Only fetches emails that were read by a user\n* `2` / `Unread`: Fetches all unread emails\n* `3` / `All`: Fetches all emails in the specified inbox of the mailbridge user","MailbridgeMailserverDataModel.process":"You can choose a process from your project, which gets executed when the mailbridge processes mails in mode Process or Both. You can use three special `$local.` variables in this process:\n\n* `$local.mail`: Contains the complete mail as an object\n* `$local.recipients`: Contains all recipient email addresses\n* `$local.sender`: Contains the sender email address","MailbridgeMailserverDataModel.errorProcess":"You can choose a process from your project, which gets executed when an error occurs while processing an email. I.e. an email with attachment, which are too big. The following `$local.` variables are provided in this process:\n\n* `$local.error`: Contains the ADITO error code\n* `$local.error`: Contains the id of the error\n* `$local.errormessage`: Contains the complete error message\n* `$local.mailid`: Contains the id of the email. This can be used to process the mail separately.","MailbridgeMailserverDataModel.attachmentHandling":"Determines how to process mails with attachments.\n\n* `ALL`: Reads all attachments, should the email together with its attachments exceed the file size set in the `mailGlobalMaxSizeRecieve` property or in the maximum size column of the mailbridge config, the email is not processed and an error gets thrown.\n* `THRESHOLD`: Reads the email and all attachments, whose file size is below what’s set in the `mailGlobalMaxSizeRecieve` property or in the maximum size column of the mailbridge config. Every attachment that’s bigger gets returned as an empty file.\n* `NONE`: Only reads the email, attachments are replaced with empty files.","MailbridgeMailserverDataModel.maxMailSize":"Overrides the `mailGlobalMaxSizeRecieve` property.\n\nWith this a mailbridge may handle bigger files or be restricted to smaller files than specified in the global property.","PreferencesDataModel.customProperties":"Here an administrator / developer can define custom configurations, which can be read via JDito","PreferencesDataModel.mailGlobalUserServerEnabled":"Specifies whether user mail (querying a mailbox per user) is turned on.","PreferencesDataModel.jditoUserServerContext":"Specifies the user who is used in the servercontext.","PreferencesDataModel.mailProcessBridgeModes":"Specifies what should happen when you pick up new user mails:\n\n* `None`: no action is taken.\n* `Process`: only the process is executed, i.e. the mail is only processed and the original mail is forfeited.\n* `Copy`: The mail is only copied to the mailrepository, but not processed.\n* `Both`: The process is executed and the mail is copied to the repository.\n\nThis setting corresponds to the `Bridgemode` setting in the mail bridge.","PreferencesDataModel.timerPreferencesAlias":"The alias where timers should be saved.","PreferencesDataModel.calendarCategories":"Here you can create, edit and delete calendar categories for tasks.\n\nThe categories defined here are offered in the task frame as a list for selection. The task is displayed in myADITO in the color specified\nfor `calendarCategories`.\n\n<!--VSCODE_ONLY-->","PreferencesDataModel.multilingualismLocale":"Specifies which language to use if the internal language of the client operating system cannot be found.\n\nThe ADITO default language is English (`en`). A different language can be used here.","PreferencesDataModel.ckeditorAIAlias":"Specifies an alias for the CKEditor AI features.\nThe alias provides information about the endpoint URL, token and extra request parameters to be used for the prompts.","PreferencesDataModel.securityPasswordMinimumLength":"Specifies the minimum length of a password. Valid value is a positive integer.","PreferencesDataModel.natsServiceEnabled":"Defines if the nats service is enabled and the server and client should connect to it.","PreferencesDataModel.helpLocation":"Specifies the URL of the help link in the navigation bar (either relative or absolute).\nFor absolute URLs the protocol must be specified, e.g. https://www.adito.de/\nIf set to null, the help link will be hidden.\nDefault = \"/client/USERHELP/overview\"","PreferencesDataModel.ckeditorDefaultAISystemPromptProcess":"Specifies a process that returns the default AI system prompt that should be used for AI requests from the CKEditor.\nThe default prompt can be overwritten by the property ckeditorAISystemPromptProcess in the entityField of the CKEditor.\nThe process should return a string that describes how the AI should behave.\nThe default CKEditor prompt is the following:\n\"Your task is to generate HTML content accordingly to the given instruction. Never include img tag in your response even if asked for.\nYour answer must be a well-structured and properly formatted HTML code. Answer only with the generated HTML content.\nDo not add any additional remarks or notes. Do not act like a chatbot or a real person.\"","PreferencesDataModel.homeLocation":"Specifies the home location for all users.\n\nPossible values:\n\nDashboards:\n- Home/full\n- SalesDashboard/full\n- ...\n\nContext:\n- Person/filter\n- Organisation/filter\n- Organisation/full?id=289791ae-4f70-4d04-a1f3-fed33341675c\n- ...\n\nDefault: Home/full","PreferencesDataModel.ckeditorDefaultAICommandsProcess":"Specifies a process that returns the default AI commands that should be visible in the CKEditor.\nThe default commands can be overwritten by the property ckeditorAICommandsProcess in the entityField of the CKEditor.\nThe process should return an array with JSON objects that contain the following\nproperties: e.g. [{ groupId: customGroupId, groupLabel: My group of commands,\ncommands: [ { id: translateSpanish, label: Translate to Spanish, prompt: Translate this text to Spanish. }, { id: explainFive, label: Explain like I'm five, prompt: Explain this like I'm five years old. } ] }]\nConsult the CKEditor Documentation for more information.","AbstractMajorDataModel.title":"Title (speaking name. may contain spaces and special characters.)\nThis has different effects depending on the entity:\n\n* System, Application, Template, Language and Alias: no effect\n* Frame, NeonFrame: Caption of the frame in the client\n* Process: Name of the process in system administration\n* Report: Labeling of the report in the client\n* Role: Name of the role as it appears in the client","PreferencesDataModel.calendarUserSorting":"The user collation allows you to configure the collection of users in the calendar.\n\nThe following settings are possible: `FIRSTNAME_FIRST`, `LASTNAME_FIRST` and `TITLE`.","PreferencesDataModel.dashletstoreAlias":"The alias in which the database table for the dashlets and dashlet configurations exists.","AbstractMajorDataModel.description":"Description","PreferencesDataModel.compressBinaries":"Indicates whether the binary data in the `ASYS_BINARIES` system table is compressed.\n\nIf this property is enabled, documents can no longer be found by using the index search.","PreferencesDataModel.userdirectoryAlias":"The alias in which the database table for the user directory/user data exists.","IDocumentationableDataModel.documentation":"Contains the documentation of the data model in the popular AsciiDoc format (`.adoc`).\nThe documentation should be set by the developer to explain different aspects (like purpose, concept, etc.) of the data model that they designed.\n\nYou may want to add the extension \"AsciiDoc\" to your ADITO Designer in order to modify AsciiDoc files.\n\n<!--VSCODE_ONLY-->","AbstractMajorDataModel.comment":"Property to store a developer comment in form of\n\n```js\n/**\n*\n*/\n```\n\nIn the past this was used in customizing for frame controls additional settings, such as the activation of rights, histories, or attributes.\nThis should not be done anymore in the `comment` property, because therefor a `metadata` property exists.","PreferencesDataModel.compressMailrepository":"Specifies whether the data is compressed in the mail repository (for mail repository DB only), in the `ASYS_MAILREPOSIT` table.","PreferencesDataModel.notificationcenterAlias":"The alias in which the database table for the notification center exists.\nConfiguration and notifications are stored in those tables.","PreferencesDataModel.mailProcessUseOutbox":"Specifies whether to copy outgoing messages from user-mail to the outbox folder of each mailbox.","PreferencesDataModel.blobPreviewSize":"Specifies the size of the previews generated für binary files.\n\n* `NONE`: No preview\n* `LOW`: 100x100px\n* `MEDIUM`: 300x300px\n* `HIGH`: 1000x1000px\n\nThis configuration only affects previews generated after changing this setting. Already generated previews will not be converted.","PreferencesDataModel.tagAlias":"The alias in which the database table for the tags exists.\nFavorites and hashtags are stored in those tables.","INeonPropertyIconDataModel.icon":"Image.\n\nDepending on the datamodel, this has different effects:\n\n* Entity: used as symbol in the designer. Do not confuse this property with the `iconId` property\n* Context: used as symbol in the designer. If the contexts entity has an icon set, the entities icon is used\n* System, Language, Role, Application: icon that appears only in the designer.\n* Template: Same effect as on the respective component\n* Alias, User: no effect\n* Frame, Process, Report, NeonFrame: icon that appears in the designer and in the client for the frame.\n\n<!--EOF-->\n\nYou can add a custom icon by placing an `icon.png` file in the folder of your data model.","PreferencesDataModel.blobHandlingMethod":"Specifies if BLOB data is stored in the database or otherwise handled by a special process.\n\nFor example this enables you to store BLOBs in files on a volume instead of the database.\nThis can improve the performance of the database in the long run.\n\n* `DATABASE`: BLOBs are handled by the core and subsequently stored in the database in the table where the BLOBs metadata is also stored (`ASYS_BINARIES`).\n* `PROCESS`: BLOBs are handled by a process (`blobHandler`).","PreferencesDataModel.permissionsAlias":"The alias in which the database table for permissions exists.\nPermissions are stored in that table.","INeonPropertyIconDataModel.iconProcess":"Specifies the icon dynamically. If the icon has no effect, neither will the result of the process.\n\nDepending on the datamodel, the result of the process has to be different:\n\n* When you can specify an icon-avatar-text (e.g. `VAADIN:USERS`): You've to return the `icon-avatar.text` with `result.string(...)`\n\n* When you can specify an image in the icon: This is returned as a string with the ID of the image in the `ASYS_BINARIES` via `result.string()`.\n\nError messages from this process do not arrive at the client, they are only visible in the server log.","PreferencesDataModel.blobStorageAlias":"The alias that points to an S3 compatible storage system.\nHere we can only have an alias of the type S3-storage.\n\nThis is only considered if the `blobHandlingMethod` was set to `S3`-storage.","PreferencesDataModel.indexsearchGlobalEnabled":"Sets whether index lookup is available in clients.\n\nIf this setting is disabled, the index search field disappears from the clients for the users. However, you can still run evaluations with `indexsearch.search()`.","PreferencesDataModel.indexsearchGlobalUseRankedSearch":"Specifies whether the client's global lookup component performs the weighting of each document, based on the boost settings of each index group.\n\nThe default is `true`.","PreferencesDataModel.indexsearchGlobalFilterExtensionHandlingMethod":"Specifies how unknown filter extensions are handled in the overall index search. Default is `FAIL`.\n\nThis setting applies to the clients index lookup and the search via JDito `indexsearch.search`.\n\n**IMPORTANT:** This does not affect entities or any consumer using an index record container.\nThey will always fail on unknown pattern extensions, since they evaluate all extensions specified in the record container.\n\n**WARNING:** If filter extensions are used in the permissions, the setting will most likely bypass the application of the filters\nfor the index search if not set to `FAIL`.\n\nCorresponding patternExtensions must be defined in the index groups, which apply the missing permissions to the index search.\n\nOptions:\n\n* `FAIL`: The index search will not return any results and throws an exception while searching via JDito.\n* `SKIP`: The index search skips all unknown filter extensions. The search is performed, but the skipped filters are not applied, returning more results than intended.\n* `AS_FIELD`: The index search will treat any unknown filter extension as an index field. The search will throw an exception if no such field is defined for the affected index groups.\n\n**NOTE:** This option will probably no longer be available when the entire index search can evaluate filter extensions.","PreferencesDataModel.indexsearchInitWaitTimeout":"Sets the maximum amount of time a running index component, e.g. the full indexer, is waiting for the index search to reinitialize, before canceling the planed execution.\n\nThe default is 10 seconds.\nThe maximum is 5 minutes and all values greater than this will result in a timeout of 5 minutes being used.\nIf the specified timeout is equal or smaller than 0 not timeout will be used.","PreferencesDataModel.indexsearchGlobalDefaultOperator":"Sets the default operator of the index search for the global search.\n\nThe default is `OR` for the optimized user search with ranking.\nIf the old search without ranking is used, `AND` is used as the default operator.\n\nIf the one value is set, the specified operator is always used as default operator for global search.\nThe operator is used for user input only and has no effect on internal filter or boost patterns of the search.","PreferencesDataModel.binariesAlias":"Here you can define the database alias which shall be used for the binaries.","PreferencesDataModel.mailProcessAssignments":"Specifies the link to the process to be executed.","PreferencesDataModel.indexsearchGlobalOnlyCountSelectedGroups":"Specifies whether the counters for index groups should only be displayed for selected groups in the global search.\nDefault is `false`.\n\nThe display then does not show any counters for the unselected groups.\nThe search is then only carried out once without having to evaluate the permissions for all global index groups.\n\nThis improves performance for large indexes and systems with complex permissions.","PreferencesDataModel.jditoCalculationDepth":"The count of JDito calculation round after which the execution is aborted. Mainly affects recursive function and their recursion depth.","PreferencesDataModel.mailEnableUserDefault":"Specifies whether to specify and use default settings for user mail. These settings are then used as default values for each user account and can be overridden there.","PreferencesDataModel.reportJasperVirtualizer":"Specifies where the data is stored when a report is generated before it is transferred to the client. Possible settings are `MEMORY` or `FILE`.","PreferencesDataModel.calendarCategoriesEvent":"Here you can create, edit or delete calendar categories for appointments.\n\nThe categories defined here are offered in the appointment frame as a list for selection. The appointment is displayed in the calendar in the color specified for `calendarCategoriesEvent`.\n\n<!--VSCODE_ONLY-->","PreferencesDataModel.multilingualismLocaleMappings":"Specifies which locales to mapped to each other.\n\nFor example, if you want all clients in Switzerland to be in English instead of in German, you can specify a new key for the Swiss locales under `Locales (All)` for the key/value pairs, and then for `Locales` the value `en` - \"English\".","PreferencesDataModel.recordContainerCachingAlias":"Alias for the Recordcontainercache","PreferencesDataModel.clientDefaultLoginLimit":"This setting determines which value to use for a client's login limit if nothing is specified by the client itself.\n\nThe login limit limits the number of possible logins for a user to the specified number.","PreferencesDataModel.securityPasswordRequiresLetter":"Specifies whether the password must contain letters.","PreferencesDataModel.databaseAuditAlias":"The database alias in which the changes in the database are to be logged in the audit table `ASYS_AUDIT`.","PreferencesDataModel.customConfigProperties":"Here an administrator / developer can define custom configurations, which can be read via JDito","PreferencesDataModel.neonClientPermissionsEnabled":"Specifies whether the permissions subsystem should be enabled","PreferencesDataModel.hashtagsEnabled":"Specifies whether the tags should be enabled or not","PreferencesDataModel.neonCallLinkSchema":"Set a custom call link schema for phone numbers (default: tel)","PreferencesDataModel.jditoCalculationVersion":"This specifies which version of the calculation logic should be used for JDito variables.\n\n`V1` is the classic calculation logic where variables are identified via static code analysis and from this the dependencies between the JDito\nscripts are calculated. In versions prior to `2023.1.0`, this was the default value.\n\nIn `V2`, the dependencies are determined at runtime via the function calls. This way cases can be identified which are not found by static code analysis. Additionally thereby also dependencies of imported libraries are found and used. `V2` has beyond that a deadlock recognition, which can break deadlocks with an exception. This prevents these errors from permanently blocking the client or server. This is the new default value as of version `2023.1.0`.\n\n`V2_FOR_CANARY` means that `V1` is used by default, but if a user has the canary role, `V2` is used for that user.","PreferencesDataModel.mailDefaultMailserver":"Specifies the default mail server that is queried if the user account does not have a mail server specified.\n\nA corresponding setting on the user account overrides this setting. Possible value: `MailserverPOP3`.","PreferencesDataModel.mailRepositoryAlias":"Specifies the alias of the database that serves as the repository.\n\nThe database must be prepared as a mail repository (see appendix system tables in the designer help). A valid database alias from the designer must be specified as a parameter.","PreferencesDataModel.calendarReminderInterval":"Specifies the interval at which to check for overdue reminders about calendar entries.\n\nThis value is expressed as a positive long value in milliseconds. If this value is set to `0`, the reminders are disabled.","PreferencesDataModel.multilingualismIndexSearchLocales":"Specifies which languages are used for multilingual fields of the index search.\n\nIf language packs are used for translation, the appropriate locales must be added to this property so that they are used by the indexer.\n\nIf a user uses a locale during the search that is not defined in this list (e.g. `de_CH`), the index search uses the corresponding locale of the language (e.g. `de`).\n\nIf no entry is defined for the language, the default locale (`multilingualismLocale`) is used.","PreferencesDataModel.localCacheMaxMemorySize":"The max size of the local cache in bytes.\nAffects in memory as well as near caches for remote caches.","PreferencesDataModel.ressourceDomain":"Domain which will be used to create the image paths of the sites userhelp. Doesn't need any trailing slashes (`/`).\nHas to be accessible from the machine which runs the designer.","PreferencesDataModel.securityPasswordRequiresNumber":"Specifies whether the password must contain numbers.","PreferencesDataModel.indexsearchFullIndexerEnabled":"Enables the full-text index.\n\nThis should only be used for the initial structure of the index, because otherwise performance problems can occur.\n\nAll data stored in the index configuration is read from the database and stored on the hard disk.","PreferencesDataModel.calendarReminderPeriod":"Specifies the amount of time to retroactively check for reminders.","PreferencesDataModel.clusterMessagingAlias":"Alias for the ClusterMessaging","PreferencesDataModel.databaseAuditInternalCaseHandling":"Sets whether the internal case handling should be used.\n\nIf this value is `No`, the query is `ASYS_AUDIT` to the system database with an `upper()` command.\n`Yes` refers to internal case handling, which is why indexes can be used in the system database, which increases performance.","PreferencesDataModel.indexsearchIndexerMaxBufferedDocs":"The maximum amount of index documents the indexer can buffer before sending them to the index.\nDefault is `256`.\n\nThe setting applies to all indexers\n\nSetting this option to `0` or less, will cause the indexer to use the default.\n\n**WARNING:** Specifying a too large amount, can lead to high memory consumption when indexing large indexes and can end up in an OOM error.\n\nSpecifying a too small amount, will result in a longer indexing time.","PreferencesDataModel.indexsearchIndexerBufferSizeLimit":"The memory limit in **bytes** of the indexers internal document buffer. Default is `512 MB`.\n\nIf the specified limit ist reached or exceeded during indexing the indexer will send all currently buffered documents to the index, ignoring the specified document limit (default `256`).\n\nThe setting applies to all indexers.\n\nThe smallest possible limit supported by the indexer is `5 MB` (5242880), all specified positiv values below this limit will result an effective limit of `5 MB`.\n\nSetting this option to `0` or less deactivates the limit.\n\n**WARNING:** When specifying a limit that is too large or deactivating the option, can lead to high memory consumption when indexing large indexes with binary data and can end up in an OOM error.\n\nThe lower the limit, the slower the indexer will be when indexing larger content, e.g. if the index group contains binary data.\n\n**NOTE**: This properties editor is a *simple long editor*, allowing to specify memory values greater then `2 GB`.\n\nThe value **must** specify the actual amount of **bytes**.\n\ne.g. `512 MB = 512 * 1024 * 1024 = 536870912 bytes`\n\n**IMPORTANT:** This option does **not** limit the actual amount of memory used by the indexer in any way.\nIt only forces the indexer to flush and commit all index documents, that are currently buffered, when the specified limit is exceeded.\nThis will only free the memory used by the buffer.\n\nThis option has no effect on the memory usage of the database requests a processes used to create the resulting index documents.","PreferencesDataModel.managerBackendAlias":"Alias for the Manager Backend","PreferencesDataModel.indexsearchIndexerWarnOnSkippedDBRows":"Specifies whether the indexer should log a warning if records of the database were skipped during indexing.\n\nDefault is `true`.\n\nThis occurs if the SQL of the indexer returns records for a different UID than specified in the indexer.\nFor example, this applies to the affectedIds of the incremental indexer.\n\nThe warning is logged to indicate a possibly incorrect SQL for the indexer of an index group.\n\nThe FullIndexer ignores this limit because there are no restrictions for the UIDs.","PreferencesDataModel.processHistoryLimit":"Defines the maximum number of entries in the process history.","PreferencesDataModel.messageQueueAlias":"Alias for the MessageQueue","PreferencesDataModel.pdfPreviewAlias":"Alias for the PDFPreviewService","PreferencesDataModel.indexsearchIndexerDBRowsForDocumentWarningLimit":"Returns the limit for the indexer, above which a warning is logged that too many db columns are read for a single record.\n\nThe default is `200` db columns per record.\n\nThe limit refers to the read db columns for a single UID of an index document and used only when the records for an index document are read out via a SQL query.\n\nWhen the limit is reached, a warning is logged that the given SQL query may have an error for the affected index group, causing too many columns to be read out for a single UID.\n\nThis waning can help to detect problems in the SQL of the indexer at an early stage.\nThe limit applies to all indexers (Full and Incremental).\n\nIf the value is set to less `0` or less, no warnings are logged.","PreferencesDataModel.jditoMaxContentSize":"Sets the maximum size of loaded objects within JDito (for example, loaded via `fileIO.getData()`).\n\nIt is specified in bytes and should be incremented if the corresponding errors appear in the log. The default value is 10 MB (10485760 bytes).","PreferencesDataModel.mailCheckerEnabled":"Specifies whether to automatically check for new messages for each user.","PreferencesDataModel.mailRepositoryPreventDuplicates":"Determines whether to check whether an email object already exists in the repository or not.\n\nIf this property is `Yes`, no duplicate entries are stored in the repository. A hash value is calculated for the check.","PreferencesDataModel.maxEntryLifetimeInCache":"The amount of time that an element remains in the cache.\nAffects in memory as well as near caches for remote caches.\nThe input is alphanumeric:\n\n* `1W` = one week in ms\n* `1D` = one day in ms\n* `1H` = one hour in ms\n* `1M` = one minute in ms\n* `1S` = one second in ms\n\nExample input: 1D 42M \n\nDefault value = 4H","PreferencesDataModel.contentAnalysisAlias":"Alias for the Content Analysis","PreferencesDataModel.relativePathToRessources":"Path to the images. Per default points to the binaryUrlRessourceHandler.","PreferencesDataModel.securityPasswordRequiresSpace":"Specifies whether the password must contain spaces.","PreferencesDataModel.indexsearchFullIndexerInterval":"The interval at which the full-text index is updated.\n\nIn almost all cases, the interval should be `0` and `indexearchFullIndexerEnabled` should be checked, since the indexer can be triggered via `indexsearch.runIndexer()`.","PreferencesDataModel.webservicesServerStyle":"Specifies the style of the webservice (`RPC/literal` or `document/literal wrapped`).","PreferencesDataModel.mailGlobalPrefetchEnabled":"Optimization parameters, immediately fetch all necessary properties for a mail from the IMAP.","PreferencesDataModel.textAnalysisAlias":"Alias for the text analysis service.\n\nIf no alias is configured the internal implementation is used.\nThe service is used to analyze and search contents of text, e.g. by the script function `text.analyze(...)`.","PreferencesDataModel.jditoScriptCacheTimeout":"Sets the amount of time to precompile JDito code.\n\nBy default, this value is set to one day. Higher values ensure that code is kept in memory and does not always need to be recompiled-this can relieve the CPU of the ADITO server and reduce latency, significantly increasing memory consumption.","PreferencesDataModel.mailCheckerUserDefault":"Specifies whether to set the default (default user) setting for automatic email checking.\nSpecifies the default mail server that is queried if the user account does not have a mail server specified.\n\nA corresponding setting on the user account overrides this setting. Possible value: `MailserverPOP3`.","PreferencesDataModel.clientTempPath":"Specifies the default value for the client's temporary path. If a temporary path is not set on the client, it is used. The value is freely selectable as a string (path specification).\nYou must enter a directory path that the client user has read and write access to. If this is not granted, there may be problems with document folders.\n\nDifferences between ADITO4 and ADITO 5:\n\nIn ADITO 5, there is no difference between `$TEMP` and an empty entry.\n\nIn ADITO4:\nIf the default temp path is left empty `$USERHOME/.adito4/temp`. \n`$TEMP` reads `java.io.TempDir`. This is `% temp%` (Windows) or `/tmp` (Linux).","PreferencesDataModel.securityPasswordRequiresSpecial":"Specifies whether the password must contain special characters.","PreferencesDataModel.indexsearchIncrementingIndexerEnabled":"Enables the incremental index.\n\nThis updates the index with the changes that have been made at a specific interval (`indexsearchIncrementingIndexerInterval`). Only small areas are updated here, not the entire index.","PreferencesDataModel.jditoScriptManagerNext":"Enables the ScriptManagerNext, which pre compiles libraries for better performance.","PreferencesDataModel.mailGlobalUserServerMinIntervall":"Specifies the interval at which to check for new messages for each user. A corresponding setting in the user account (mail server checker interval [MS]) overrides this global variable.","PreferencesDataModel.securityPasswordValidityTime":"Specifies the number of days after which the password expires. The number of days is expressed as a positive integer. If `-1` is specified, the password does not expire and is valid forever.","PreferencesDataModel.databaseAuditFilterDBSyncItems":"Enables the database filter for synchronization items.\nThis suppresses the writing of the data records that come from the other system during synchronization.\nThis setting is useful on the slave, so that the changes that come from the master are not also entered into the audit layer.\n\nAttention: This makes it impossible to track the changes on the slave.","PreferencesDataModel.indexsearchIncrementingIndexerInterval":"The interval at which the incremental index is updated.\n\nThe minimum value that can be set is one second (1S), the recommended minimum value is 15S. If `0` is entered here, the indexer is not active.","PreferencesDataModel.securityPasswordRequireRecentAlgorithm":"The user is forced to assign a new password if the old password is not hashed with the latest security hash algorithm.","PreferencesDataModel.securityApplyPasswordPoliciesForTechnicalUsers":"Provides the ability to disable password policies for users with the `TECHNICAL` role.","PreferencesDataModel.securityPasswordHistory":"Specifies the number of passwords stored in the password history.","PreferencesDataModel.databaseAuditProcessLoggerUser":"The user that is used for the audit logging process.","PreferencesDataModel.indexsearchIncrementingIndexerBunchSize":"The number of data packets that the incremental index enters in a turn.","PreferencesDataModel.databaseAuditGetOldValueLobs":"Sets whether the old LOB values (CLOB, BLOB) are given to the audit.\n\nAs a result, the audit is slower and consumes more memory.","PreferencesDataModel.projectName":"The name of the project","PreferencesDataModel.databaseAuditDoDifferencesOnlyOnUpdate":"If set, only the changed elements are written to the audit layer","PreferencesDataModel.defaultSystemAlias":"The default alias for all system tables.\nExceptions are all tables that are affected by defaultDataAlias.\n\nCurrently, these tables are potentially affected by this property:\n\n* `ASYS_DASHLETCONFIGURATIONS`\n* `ASYS_DASHLETS`\n* `ASYS_NOTIFICATIONCONTENTS`\n* `ASYS_NOTIFICATIONS`\n* `ASYS_PERMISSION`\n* `ASYS_PERMISSIONACTION`\n* `ASYS_PERMISSIONSET`\n* `ASYS_RECORD`\n* `ASYS_RECORDGROUP`\n* `ASYS_ROLES`\n* `ASYS_ROLES_CHILDREN`\n* `ASYS_USERS`\n* `ASYS_USERTOKEN`\n\nThe following tables are mandatory in the system alias and can't be influenced by this property:\n\n* `ASYS_ALIASCONFIG`\n* `ASYS_ICONS`\n* `ASYS_MONITOR_DASHLETCONFIG`\n* `ASYS_SEQUENCES`\n* `ASYS_SYSTEM`\n\nThe following tables are also not influenced by this property because their alias is determined by special configurations that can't be overridden in a sensible way:\n\n* `ASYS_AUDIT`\n* `ASYS_CALENDARLINK`\n* `ASYS_FARM`\n* `ASYS_FARM_CLIENT`\n* `ASYS_MAILREPOSIT`\n* `ASYS_MAILREPOSIT_HASH`\n* `ASYS_SYNCSLAVES`\n* `ASYS_TIMERS`\n* `ASYS_TIMERS_SERVERRUNS`\n* `ASYS_UIDRESOLVER`","PreferencesDataModel.defaultDataAlias":"The default alias for all data tables.\nAs of now, only the following tables are potentially affected by this property:\n\n* `ASYS_BINARIES`\n* `ASYS_CALENDARBACKEND`\n* `ASYS_CALENDARSYNC`\n\nThe following tables are mandatory in the system alias and can't be influenced by this property:\n\n* `ASYS_ALIASCONFIG`\n* `ASYS_ICONS`\n* `ASYS_MONITOR_DASHLETCONFIG`\n* `ASYS_SEQUENCES`\n* `ASYS_SYSTEM`\n\nThe following tables are also not influenced by this property because their alias is determined by special configurations that can't be overridden in a sensible way:\n\n* `ASYS_AUDIT`\n* `ASYS_CALENDARLINK`\n* `ASYS_FARM`\n* `ASYS_FARM_CLIENT`\n* `ASYS_MAILREPOSIT`\n* `ASYS_MAILREPOSIT_HASH`\n* `ASYS_SYNCSLAVES`\n* `ASYS_TIMERS`\n* `ASYS_TIMERS_SERVERRUNS`\n* `ASYS_UIDRESOLVER`","PreferencesDataModel.databaseAuditIsUseOldValuesOnDelete":"If set, only the deleted elements are provided within the audit layer","PreferencesDataModel.indexsearchMaximumHits":"Number of maximum search results displayed in the index search. Since the index search should only give an overview, you should not enter too large values here.\n\nBecause the index always sets the result set to the size of the maximum hits and then takes the search results, it can also lead to performance degradation in this field.\n\nThis setting is overridden by `indexsearchDefaultHits`, should `indexsearchMaximumHits` be the greater value.\n\n`indexsearchMaximumHits` is only relevant for `indexsearch.search()` and causes you to be able to filter only up to the specified number.","PreferencesDataModel.neonRequestHeaderSize":"Sets the maximum size for the request headers","PreferencesDataModel.mailBridgeMailserver":"Specifies a mail server that the bridge should query. The parameter specifies the name of a server alias of the type mailserver IMAP or mail server POP3. At this point, a wizard can be used to specify how the Mailbridges should behave.\n\n<!--VSCODE_ONLY-->","PreferencesDataModel.databaseAuditTimestampResolution":"Audit timestamps have to be unique. Here you can configure, which distance between the timestamps is used.","PreferencesDataModel.indexsearchGlobalUseLanguageFallback":"Specifies whether the global search, for a multilingual index, should search the system's default language in addition to the client language.\n\nDefault is `true`.","PreferencesDataModel.indexsearchGlobalMinTermSizeForWildcards":"Defines the minimum length that an input value of the global search must have, so that the extension with wildcards is applied for the value.\n\nDefault is `0` for no limit.","PreferencesDataModel.indexsearchGlobalFuzzySearchFactor":"Returns the factor used by the fuzzy search.\n\nThe factor determines whether and how many character permutations the fuzzy search may perform for individual terms. \n\nThe default is `1`. \n\n> **NOTE:** The setting is only applied if the ranked search is used. `indexsearchGlobalUseRankedSearch`\n\nValid values are:\n* `0`: The fuzzy search is deactivated.\n* `1`: The fuzzy search performs **one** permutation.\n* `2`: The fuzzy search performs **two** permutations.","PreferencesDataModel.mailBridgeMaximumAbsoluteDelay":"Maximum, absolute delay in milliseconds, if the delay is 0 no delay is applied","PreferencesDataModel.clientSearchExcludeForIgnorecase":"Enables case-sensitive in client search.\n\nIf the checkbox is checked, the client search will be case-sensitive for components of type char.","PreferencesDataModel.databaseAuditMaximumTimestampJitter":"The maximum deviation from the last value. Used to account for changes to the system time","PreferencesDataModel.indexsearchAllowLeadingWildcards":"Allows leading wildcards (`*criterion`).\n\nIf this is not allowed, only the following wildcards (`criterion*`) are accepted.","PreferencesDataModel.indexsearchDefaultResultCount":"Sets the default amount of hits, if in JDito a specific count is not given. Has to be lower or equal to `indexsearchMaximumHits`.","PreferencesDataModel.indexsearchCachePatternExtensions":"Specifies whether the filter patterns of the PatternExtensions should be cached by the index for later reuse of the results.\n\nDefault is `true`.","PreferencesDataModel.indexsearchCachePermissionFilters":"Specifies whether the filter patterns for the permissions should be cached by the index for later reuse of the results. \n\nDefault is `true`.","PreferencesDataModel.indexsearchBoostLatestDocuments":"If enabled newer documents get a boost to score higher than older documents.","PreferencesDataModel.mailGlobalMaxSizeReceive":"Specifies the maximum size, in bytes, of a received email message. The value is freely selectable as an integer.","PreferencesDataModel.useModernImplementation":"If set to \\\"true\\\" enables the new database layer backed by MyBatis","PreferencesDataModel.indexsearchJDitoResultFieldArraysAsString":"Defines whether results, for fields with multiple values, should be returned as a string instead of an array.\nAffected are all IndexRecordFields where the property `isMultiValued` is set.\nThis only affects the result of the search via JDito, using `indexsearch.search()` or `indexsearch.searchIndex()`.\nDefault is `false`.\n\nIf set to `true`, all arrays will be returned as strings, with the form `[value1, value2, ..., valueN]`.\nIf `false`, the values are returned as native arrays.","PreferencesDataModel.indexsearchCJKOptimizationEnabled":"Controls the advanced optimization for CJK inputs of the index search.\n\nDefault is `true`.\n\nIf the flag is active, additional search options, such as word shingles, additional phrases and separate wildcard settings are used for CJK entries.\nThe individual options can be configured in more detail via the corresponding expert parameters.","PreferencesDataModel.indexsearchCJKOverrideUserWildcards":"Specifies whether other wildcard settings should be used for CJK terms.\n\nDefault is `false`.\n\nIf active, the wildcards for CJK terms are determined by the two settings `indexsearchCJKApplyLeadingWildcards` and `indexsearchCJKApplyTrailingWildcards`, instead of the default user setting.","PreferencesDataModel.indexsearchCJKApplyLeadingWildcards":"Specifies whether leading wildcards should be added to CJK terms.\n\nDefault is `true`.","PreferencesDataModel.indexsearchCJKApplyTrailingWildcards":"Specifies whether trailing wildcards should be added to CJK terms.\n\nDefault is `true`.","PreferencesDataModel.indexsearchCJKCreateShingles":"Specifies whether shingles are to be generated for CJK terms.\n\nDefault is `true`.\n\nThe length of the generated shingles is set via the corresponding parameters `indexsearchCJKMinShingleSize` and `indexsearchCJKMaxShingleSize`.\nThe shingles are generated only for terms, greater or equal, of the set minimum length.\nThe minimum term length can be set via the parameter `indexsearchCJKMinTermSizeForShingles`.","PreferencesDataModel.indexsearchCJKMinTermSizeForShingles":"The minimum length for CJK terms from which shingles are generated. Default is 4.","PreferencesDataModel.indexsearchCJKMinShingleSize":"The minimum length for the generated shingles for CJK terms. Default is 3.","PreferencesDataModel.indexsearchCJKMaxShingleSize":"The maximum length for the generated shingles for CJK terms. Default is 4.","PreferencesDataModel.indexsearchCJKCreatePhraseTerms":"Specifies whether additional phrases should be generated for CJK terms for the individual terms.\n\nDefault is `true`.","PreferencesDataModel.indexsearchCJKOnlyUsePhraseTerms":"Specifies whether all terms are to be evaluated as phrases for CJK terms.\n\nDefault is `false`.","PreferencesDataModel.indexsearchUseRemoteParameterSets":"Specifies if the index should use parameter sets that are managed by the remote service.\n\nDefault is `true`.\n\nIf enabled, the default, all field aliases used during a search will be stored on the remote service and are only referenced in the query.\nThis reduces the length of the used URL of the search request.\n\nIf disabled, all needed field aliases for the search are send in as a URL parameter of the search request.\nThis can case an exception caused by exceeding the max length of a URL, if to many field or languages are used for the index.","PreferencesDataModel.mailGlobalMaxSizeSend":"Specifies the maximum size, in bytes, of a mail to send. The value is freely selectable as an integer.","PreferencesDataModel.clientStorePreferecensAtLogout":"Specifies whether the preferences should be saved only when the client is stopped or when a search is performed in the user data model of the user who is currently logged on.","PreferencesDataModel.indexsearchAutoCommitEnabled":"Specifies if pending updates of the indexer will be automatically pushed to the index. \n\nThe default is `true`.\n\nIf the auto commit flag is set to `false`, then only explicit commits will update the index.\nThis setting should only be set to `false` if the whole index contains less then 30000 documents","PreferencesDataModel.mailBridgeMaximumRelativeDelay":"Maximum, relative delay to the interval in percent, if the delay is 0 no delay is applied","PreferencesDataModel.clientHideFloatingActionButton":"Indicates whether the Floating Action Button is hidden.\n\nIf this property is enabled, the Floating Action Button will be hidden.\n\nWith the floating action button hidden, it's not possible to access the actions located within it, and there is no alternative for these actions.","PreferencesDataModel.indexsearchSoftAutoCommitEnabled":"Specifies if the indexer performs a 'soft commit', meaning that Solr will commit your changes to the Lucene data structures quickly but not guarantee that the Lucene index files are written to stable storage.\n\nThe default ist `false`.\n\nThis is an implementation of Near Real Time storage, a feature that boosts document visibility, since the Searcher does not have to wait for background merges and storage to finish.\n\nNote when using 'soft commits' and the index server crashes, all not fully committed documents are lost, even if there were visible for the searcher.","PreferencesDataModel.indexsearchAutoCommitMaxTimeMS":"The number of milliseconds since the oldest uncommitted update of the indexer.","PreferencesDataModel.indexsearchAutoCommitMaxDocs":"The number of updates that have occurred since the last commit of the indexer.","PreferencesDataModel.indexsearchUseSearchableTitleField":"Specifies if the system field `#TITLE` (\\_title\\_) of the index search can be searched. The default is `false`.\nThis option affects all index groups and enables the `isIndexed` flag of the system field.\nWhen changing this setting, the index must be rebuilt for it to take effect.","PreferencesDataModel.indexsearchUseSearchableDescriptionField":"Specifies if the system field `#DESCRIPTION` (_description\\_) of the index search can be searched. The default is `false`.\nThis option affects all index groups and enables the `isIndexed` flag of the system field.\nWhen changing this setting, the index must be rebuilt for it to take effect.","StaticContentEntryDataModel.key":"the mode of the view. Note that every view should only be referenced once","StaticContentEntryDataModel.value":"the provider of the entity","SubreportDataModel.reportData":"the subreport","IInstanceConfigurationDatabaseDataModel.systemDBRequestWarnTimeout":"Specifies the query timeout for the system database. This is not a \"real\" timeout, but after this period of time in the client,\nthe user is asked whether the long running database query should be interrupted or continue to run.\nThe value is specified as a positive long value.","IInstanceConfigurationWebservicesDataModel.jditoWebserviceMaxQueued":"The maximum number of requests that can be queued when all core worker threads are busy.\n* If the value is `0`, no queue is used and calls are rejected when no worker thread is immediately available.\n* If the value is `-1`, an unbounded queue is used and calls are never rejected.\n\nWhen no current existing worker threads are available to process a request but the `maxThreads` limit has not been reached, calls will be still queued first.\n\nNOTE: Read more about this in the official platform documentation.","IInstanceConfigurationWebservicesDataModel.jditoWebserviceMaxThreadCount":"The maximum number of threads available to process requests.\n\nThis setting defines the upper thread limit before requests are **rejected**. It does not specify how many threads are initially\navailable.\n\nWhen a queue size is defined by the property `jditoWebserviceMaxQueued`, the server will prioritize queuing requests first,\nand only create new threads once the queue is full.\nTo increase the number of active threads from the start, use `jditoWebserviceMinThreadCount`.\n\nNOTE: Read more about this in the official platform documentation.","IInstanceConfigurationWebservicesDataModel.jditoWebserviceMinThreadCount":"The minimum number of threads waiting to process requests, even if they are idle.\nIn technical terms, this is the core number of threads that are spawned on server start.\n\nNOTE: Read more about this in the official platform documentation.","IInstanceConfigurationDatabaseDataModel.systemDBRequestTimeout":"After this time a database query is definitely interrupted.\nThe value is specified as a positive long value and should be greater than the systemDBRequestWarnTimeout value.","AliasDefinitionCloudServiceDataModel.image":"Image coordinate\ne.g. on Dockerhub: `adito/cloudmanager`","AliasDefinitionCloudServiceDataModel.tag":"Image tag\ne.g. `latest`, `2023.0.1`, `1.0.0`","AliasDefinitionCloudServiceDataModel.port":"Port which will be used for communication. If the used image requires the use of a specific port, set it here.\nIf no port is configured the default `port` 8080 will be used.","AliasDefinitionCloudServiceDataModel.mountPath":"The path under which a persistent volume will be mounted. Can be used to store files that should be kept between restarts of the application.\nIf this path is changed after files have already been stored, they may get lost!\nExample:\n`/opt/mosaico/uploads/`\nThis property is optional, if empty, no volume will be mounted.","AliasDefinitionCloudServiceDataModel.envVars":"Environment Variables which will be set on the container.\nThe variables have to be comma separated ('`,`')\nExample:\n`myEnv=123,ThisIsAlsoValid,ThisWillWorkToo=`","AliasDefinitionCloudServiceDataModel.publish":"If an application is published, it is publicly accessible from the internet.\nYou can reach your service via `https://[host]/services/cloud/cloudservice-[aliasDefinitionName]`","AliasDefinitionPluginDataModel.pluginGroupId":"The coordinates of the plugin jar in maven.\nThis is the plugins group id, according to maven coordinates.","AliasDefinitionPluginDataModel.pluginArtifactId":"The coordinates of the plugin jar in maven.\nThis is the plugins artifact id, according to maven coordinates.","AliasDefinitionPluginDataModel.pluginVersion":"The coordinates of the plugin jar in maven.\nThis represents the plugins version.","CustomBooleanPropertyDataModel.property":"Custom defined boolean-property which is not autogenerated by the Designer but instead was created by the user","AbstractCustomPropertyDataModel.description":"the description of this element","AbstractCustomPropertyDataModel.global":"If this property should be global or not","CustomDurationPropertyDataModel.property":"Custom defined `duration` property which is not autogenerated by the Designer but instead was created by the user","CustomIconPropertyDataModel.property":"Custom defined icon-property which is not autogenerated by the Designer but instead was created by the user","CustomIntegerPropertyDataModel.property":"Custom defined number-property which is not autogenerated by the Designer but instead was created by the user","CustomJDitoPropertyDataModel.property":"Custom defined JDito property which is not autogenerated by the Designer but instead was created by the user.\nYou can define JDito code via the editor in this property, which may be later used and executed.","CustomPasswordPropertyDataModel.property":"Custom defined password property which is not autogenerated by the Designer but instead was created by the user","CustomStringPropertyDataModel.property":"Custom defined string-property which is not autogenerated by the Designer but instead was created by the user","EntityDependencyDataModel.entityName":"Name of the linked entity that acts as the provider.","EntityDependencyDataModel.fieldName":"Name of the field via which the dependency is established, e.g., the name of a provider.\n\nMust be a field of the entity specified in `entityName`","IEntityDataModel.entityFields":"List of fields, providers, consumers, etc. for this entity","IEntityBaseDataModel.title":"Singular title of the model, e.g. Surname","IEntityBaseDataModel.description":"Short technical description of the model in plain text.","INeonPropertyActionOrderDataModel.actionOrder":"Order of the actions","INeonPropertyPermissionableDataModel.usePermissions":"Determines if the element is relevant for the authorisation concept. For example: If this value is `true` the element can be selected for the grant configuration within the client","INeonPropertyTitleProcessDataModel.titleProcess":"Process to determine the title dynamically. This will overwrite the value of the `title` property and is for example displayed in the views within the client.","INeonPropertyActionDataModel.onActionProcess":"Process that is executed during the action (e.g. double-click).","INeonPropertyStateDataModel.state":"Determines the state of an element, for example: element can be edited, element is not visible, element is inactive, etc.\n\nBe aware that the concrete impact depends on the element where this property is set:\n\nIf you take a look at the read-only-value for example:\n* In a recordField this will affect only the field where the `state` property has been set.\n* In a consumerField all the recordFields within there will be readOnly, and you're not able to add, modify or delete records.\n\nNote when the value `AUTO` is set, that the state does depend on different factors like \"In which operatingstate is the record?\".","INeonPropertyTooltipDataModel.tooltip":"Tooltip. Text that is displayed when the mouse is driven over a component.","INeonPropertyStateDataModel.stateProcess":"A process that can determine the state dynamically. You have to return the corresponding state in the process with `result.string(...)`\nThis will overwrite the value set in the `state` property.\n\nExample: \n\n```js\nresult.string(count > 0 ? neon.COMPONENTSTATE_DISABLED : neon.COMPONENTSTATE_AUTO);\n```\n\nNote that this property may be internally overwritten (for example if the user has no grants).","INeonPropertyTooltipDataModel.tooltipProcess":"Process of tooltip labeling.\n\nHere, each string can be returned by `result.string()`. control characters (e.g. `\\n`) are evaluated to display new rows, for example.\n\nHTML is not possible here. \n\nIf the component's content goes beyond the component, the first line of the ToolTip always displays the entire contents of the component. \n\nThis process overrides the `toolTip` property.\n\nError messages from this process do not arrive at the client, they are only visible in the server log.","INeonPropertyIconIdDataModel.iconId":"The icon is displayed in various situations in the client as symbol for an entity.\n\nFor example the sidebar with the list of contexts: Since every context has an entity associated, the icon of the entity is displayed.\n\nYou can access the icon via the virtual field `#ICON` if you need to.","INeonPropertyIconIdDataModel.iconIdProcess":"Basically the same as the `iconId` property, but this time it's dynamically calculated per record. This will overwrite the value that is set in the `iconId` property. This could be for example different icons for active tasks and already done tasks.","INeonPropertyShortcutDataModel.shortcut":"a shortcut for calling this action","INeonPropertyActionTypesDataModel.isMenuAction":"Determines if the action is shown in the context menu.","INeonPropertyActionTypesDataModel.isObjectAction":"Determines if the action is shown on an object.","INeonPropertyActionTypesDataModel.selectionType":"Controls if the action is enabled only when there are selected rows. Possible values:\n\n* `UNBOUND`: The action can be enabled regardless of the selection.\n* `MULTI`: The action is enabled only when one or more rows are selected. When no selection exists, it is always disabled and the stateProcess is ignored.\n\nNote that other requirements like grant-processes or permissions apply in addition to this option.","INeonPropertyActionTypesDataModel.isSaveAction":"Determines if the action is shown in the save options popup to run the action after a save operation","IIncludeInBuildDataModel.includeInBuild":"Whether this model should be included in the build process.","INeonContainerDataModel.children":"List of children in this container","EntityAggregateFieldDataModel.parentField":"Set an entity field as parent for the aggregate field.\n\nAn aggregate field alone does not work because certain properties (e.g. `contenttype`, `outputformat`...) are inherited from the parent.","EntityAggregateFieldDataModel.displayValueProcess":"The result of the process is written into the `displayValue` of the aggregate field.\n\nUse this process to format your aggregated value. You can only access values from other aggregate fields in this process.","EntityConsumerDataModel.children":"List of parameters in this consumer","EntityConsumerDataModel.title":"Singular title of the consumer, e.g. Competitor","INeonPropertySelectionModeDataModel.selectionMode":"Determines how many elements may be selected. \nFor example, select either none, one dataset or multiple datasets at a time.\n\nBe aware that the concrete impact depends on the element where this property is set:\n\nIn a recordField for example the type of the component that is rendered within the client may change (Lookup-component &lt;-&gt; List-component) while in a consumerField the records that can be selected within a table-presentation of the data may be different.","INeonPropertySelectionModeDataModel.selectionModeProcess":"A process that can determine the `selectionMode` dynamically. You have to return the corresponding `selectionMode` in the process with\n `result.string(...)`.\n \n This will overwrite the value set in the `selectionMode` property.","INeonPropertyValidationDataModel.onValidation":"The `onValidation` is executed during loss of focus to check the input for validity.\n Validations fails, if a message other than `true` is returned by `result.string()`.\n\n`result.string(\"Any Message\")` or `result.string(false)` results in failing the validation check, thus displaying the message to the user, not accepting the input data and disabling the save button.\n\nIf `result.string()` is not called or `result.string(true)` is used, the system assumes a positive validation and accepts the input data.\nThis process has to be fast, due to being called multiple times by the system. \n\n**Do not use it to change the state of components!**","EntityConsumerDataModel.refreshParent":"If any record of the consumer's entity is changed, this consuming entity will also be refreshed.","EntityConsumerDataModel.isOneToOneRelationship":"Activate the option if you want to create a one-to-one relationship between records.\n\nThe consumer can then only provide one data record. With this option, the consumer can be used in viewtemplates that can handle one data record only. E.g. in the GenericViewtemplate","EntityConsumerDataModel.externalInitFilterProcess":"In this process define an external filter that is passed to the linked entity during initialization.\n\nThe provider property `initFilterMergeMode` can be used to decide whether the filter is automatically `AND` or `OR` combined with the entity's `initFilterProcess`.\nIf the `IGNORE` option is used, the link is not made automatically and the external filter can be responded to in the `initFilterProcess`.\nThe external init filter can be obtained from the local variable `$local.filter` in the `initFilterProcess`.\n\n\nWhich data can be accessed in the process?\n\nThe process is called for each consumer when the main entity is initialized.\nNo data record has yet been loaded for the main entity. So the fields have no data yet. Parameters can be accessed normally.\n\nException: If a consumer is only used for lookups, fields can be used.\nBecause the lookup models are initialized when the user opens the lookup, all the data of the main entity is already available here.","INeonPropertyImageDataModel.image":"Image of a record in an entity (since the `image` property is static, this will affect every record).\nThis could be for example a logo. You can access the image via the virtual field `#IMAGE` (for example in a view).\n\nNote that the image is not the icon that is displayed in the client, but it is a representation of the record in an image-format.","EntityDataModel.title":"Singular title of the entity, e.g. Person","INeonPropertyTitlePluralDataModel.titlePlural":"entities title in plural; e.g. Persons\n\nThis is used within the client in views where multiple records are displayed - for example as detail-headline in a master-detail layout","IRecordContainerReferenceDataModel.recordContainer":"Configuration of the main record container of an entity.\n\nFor example, this `recordContanier` will be used for editing (new, update, delete), for default way of loading data or for providing data via a provider (if not specified otherwise).","INeonPropertyColorDataModel.color":"Defines a color for an element.\n \n Where (or if) the color is used depends on different actors in the system and is defined internally.\n Note that the color can not be chosen freely, but you can select from different presets (e.g.: `priority-high-color`).\n This will ensure that the color will fit on different themes and for example a warning-color will always stand out.","INeonPropertyImageDataModel.imageProcess":"Image of a record in an entity. Since the process can return an image dynamically this could be used for example to provide a portraits for\npersons within an `Person_entity` (=> Every person has a different portrait)\n\nYou can return any valid avatarish-value (`TEXT:MY NAME`, base64 encoded string etc.) with `result.string(...)` and the result will overwrite\nthe value that is set in the `image` property.\n\nYou can access the image via the virtual field `#IMAGE` (for example in a view).\n\nNote that the image is not the icon that is displayed in the client, but it is a representation of the record in an image-format.","INeonPropertyMetaDataModel.metadata":"Metadata field.\n\nThis corresponds to the comment property on the swing frame.\nSettings can be made here, whether rights, histories, attributes,... are activated or not.","INeonPropertyEntityFlowDataModel.onInit":"Process that is executed during initialization.","IEntityGrantCreateUpdateDeleteDataModel.grantCreate":"Specifies whether the creation of a new record is allowed in principle.","INeonPropertyColorDataModel.colorProcess":"Defines a color for an element dynamically by executing the process.\n Where (or if) the color is used depends on different actors in the system and is defined internally.\n Note that the color can not be chosen freely, but you can select from different presets.\n Within the `system.neon` module there exist constants for the different colors, e.g. `neon.PRIORITY_HIGH_COLOR` or `neon.BRAND_COLOR`.\n This will ensure that the color will fit on different themes and for example a warning-color will always stand out.","IEntityGrantCreateUpdateDeleteDataModel.grantCreateProcess":"Process for the permission to create a new record.\n\nReturns `result.string(true)` for \"allowed\", `result.string(false)` for \"not allowed\".\n\nThe return of this process overrides the `grantCreate` setting.\n\nError messages in this process occur at the client.","INeonPropertyEntityFlowDataModel.afterUiInit":"Process that is executed after the initialization of the UI (= after loading all displayed elements).\n\nThis is useful if you want to preset a consumer with records in the NEW-mode for example.","IEntityGrantCreateUpdateDeleteDataModel.grantUpdate":"Specifies whether changing a new record is allowed in principle.","IEntityGrantCreateUpdateDeleteDataModel.grantUpdateProcess":"Process for the permission to update a record.\n\nReturns `result.string(true)` for \"allowed\", `result.string(false)` for \"not allowed\".\n\nError messages from this process do not arrive at the client, they are only visible in the server log. If an error occurs in this process, the power is not granted.","INeonPropertyEntityFlowDataModel.beforeOperatingState":"Process that runs before the operatingstate is changed.","INeonPropertyEntityFlowDataModel.afterOperatingState":"Process that runs after the operatingstate is changed.","INeonPropertyEntityFlowDataModel.onValidation":"The `onValidation` is executed during loss of focus to check the input for validity.\nValidations fails, if a message other than `true` is returned by `result.string()`.\n`result.string(\"Any Message\")` or `result.string(false)` results in failing the validation check, thus displaying the message to the user, not accepting the input data and disabling the save button.\n\nIf `result.string()` is not called or `result.string(true)` is used, the system assumes a positive validation and accepts the input data.\n\nThis process has to be fast, due to being called multiple times by the system. **Do not use it to change the state of components!**","IEntityGrantCreateUpdateDeleteDataModel.grantDelete":"Specifies whether the deletion of a record is allowed in principle.","INeonPropertyEntityFlowDataModel.afterSave":"Process that is executed after the record has been successfully saved\n\nThe variable `$local.entitydata` can be used to access the data of the entity that has been saved. The recordstate (`NEW` or `EDIT`) can be retrieved via `\"$local.recordstate`.\n\nBy finishing the process with `result.string(true)`, the default behavior after saving is ignored. In this case, the process must first execute commands regarding the further navigation, e.g., `openContext(...)`. In any other case (= no result or `result.string(false)`), the default behavior is executed unchanged.\n\nExample:\nIf you use the process code\n\n```js\n[...]\nneon.openContext(\"Organisation\", [...])\nresult.string(true);\n```\n\nthen, the context \"Organisation\" is opened after saving, ignoring the user's selection, e.g., \"Save and open\" or \"Save and close\".","INeonPropertyEntityFlowDataModel.initFilterProcess":"Process that can return an initial filter (json) for the entity.\n\nThis filter is applied when the entity is loaded, afterwards the data is requested from the associated recordcontainer.\n\nNote that the result given in this process is only a preset filter that may be changed by the user either\n\n* explicit by changing it for example via the filter-menu\n* implicit for example via a search term in a lookup component\n\nThis process has to return a stringified filter-object to set (like in `entities.createRowConfig().filter(...)`) or nothing if no filter shall be set.\n\nThe filter string has to be a valid **user-filter**, additional filters like permissions are set automatically by the entity and are not required as\nresult here.\n\nFiltergroups and -rows can be combined to build up complex filters as long as the filter is valid.\n\nNote that often more complex filters are performing slower when loading data instead of simple filters.\n\nTo learn more about how the base object for the result string (so the filter object) needs to be defined take a look in the general technical\ndescription of filters in the [Customizing Manual](https://help.platform.adito.cloud/manuals/Customizing_Manual.pdf).\n\n**Code Example:**\n\n```js\nvar res;\n\n// _hasPresetFilter is in this example a private function that determines\n// if a user needs a filter preset or not\n// only add preset in the filter presentationmode \n// because we do not want to preset the filter in the lookup presentation mode \n// since the filter is discarded \n// when the user enters a search term into the lookup component\nif (vars.get(\"$sys.presentationmode\") === neon.CONTEXT_PRESENTATIONMODE_FILTER \n\t&& _hasPresetFilter())\n{\n\tvar filter = {\n\t\ttype: \"group\",\n\t\t\toperator: \"AND\",\n\t\t\tchilds: [{\n\t\t\t\ttype: \"row\",\n\t\t\t\tname: \"CURRENT_SITUATION_LOG\",\n\t\t\t\toperator: \"EQUAL\",\n\t\t\t\tcontenttype: \"TEXT\",\n\t\t\t\tkey: \"$R1258_DISABLED\",\n\t\t\t\tvalue: translate.text(\"Disabled\")\n\t\t\t}]\n\t};\n\tres = JSON.stringify(res);\n}\n\nif (res)\n\tresult.string(res);\n```","IEntityGrantCreateUpdateDeleteDataModel.grantDeleteProcess":"Process for the permission to delete a record.\n\nReturns `result.string(true)` for \"allowed\", `result.string(false)` for \"not allowed\".\n\nThe return of this process overrides the `grantDelete` setting.\n\nError messages in this process occur at the client.","EntityDataModel.siblings":"A sibling describes other entities that represent the same data as the current entity where this property can be set.\n\nFor example: You've got a `Eventparticipant_entity` that represents participants of an event and a `EventparticipantAdd_entity` that is used for adding participants of an event in a special way.\nIf you stored information within the `EventparticipantAdd_entity` this would not trigger any auto refreshes in a `Eventparticipant_entity` that is also displayed in the current client view. To resolve this problem (and to provide the information that these two entities belong together by representing the same data in different ways) you can set the siblings as follows:\n\n* `Eventparticipant_entity` is a sibling of `EventparticipantAdd_entity` \n\nand\n\n* `EventparticipantAdd_entity` is a sibling of `Eventparticipant_entity`","INeonPropertyFavoritesDataModel.useFavorites":"Determines if the views using this entity can show private tags (favorites).","INeonPropertyRecordsRecipeSelectionDataModel.recordsRecipeSupported":"Determines if the entity supports `RecordsRecipe` for selections.\n\nAn entity supports the `RecordsRecipe` if the place of use of selections (like customized selection-actions) are processing the selection via the variable `$sys.selectionRecordsRecipe`.\n\nWhen this property is disabled it tells the entity that only the legacy way for providing selections (e.g. `$sys.selections` providing UIDs of the selected items) is supported. A \"select all\"-checkbox will appear for all supported viewtemplates only if the recordContainer is not pageable.\n\nWhen this property is enabled a \"select all\"-checkbox will appear for all supported viewtemplates (like tables, cards, treetables and more) even if\nthe used recordContainer is pageable.\n\nNote that the `$sys.selectionRecordsRecipe` exists and is filled no matter of what value of this property. This property only indicates if the entity and its elements (for example customized selection-actions) are ready to handle the `$sys.selectionRecordsRecipe` variable and a \"select all\" checkbox in viewtemplates can be displayed or not.\n\nTherefore, it is possible to migrate all usage locations of the selection step by step and if everything is migrated this property can be set to `true`.","INeonPropertyCurrentContentDataModel.contentTitleProcess":"Process to determine the title based on content of a record within an entity.\n\nFor example: If you've got a `Person_entity`, the `contentTitle` could be the first- and lastname of a person separated by a space character.\n\nThe result is used for example in a list of Persons.","INeonPropertyCurrentContentDataModel.contentDescriptionProcess":"Process to determine a longer description based on content of a record within an entity.\n\nFor example: If you've got a `Person_entity`, the `contentTitle` could be the full name of a person and the persons address.","INeonPropertyValueDataModel.valueProcess":"The result of the process is written into the field. The process will not be executed when already the `recordContainer` has already set a value.\n\nIf you've got a separate `displayValue`, the `valueProcess` represents a technical value (like an ID).\n\nErrors that occur in this process are not passed to the client. These can only be found in the server log / log files.\n\nError messages from this process do not arrive at the client, they are only visible in the server log.","INeonPropertyMandatoryDataModel.mandatory":"Indicates whether this field is mandatory and the value of this field must be set.","INeonPropertyPlaceholderDataModel.placeholder":"Placeholder. Text that is displayed inline in a component.","INeonPropertyContentTypeDataModel.contentType":"Specifies the type of the content of an entity field. \n \n This setting evaluates the client's graphical component and, for example, displays a boolean renderer in a table or renders an image.","INeonPropertyFormatDataModel.resolution":"If a graphic formatting of the value is desired, this is specified here.\n\nCurrently, this setting can only be used for date values and time units.","INeonPropertyValueDataModel.displayValueProcess":"The result of the process is written into the `displayValue` of the field.\nThe process will not be executed when the `recordContainer` has already set a `displayValue`. Note that you may need to specify the `displayValueProcess` in addition in certain situations (for example if your field is editable)\n\nYou should only set the `displayValue` if you've got a value (see `valueProcess`).","INeonPropertyMandatoryDataModel.mandatoryProcess":"The return value (boolean) indicates whether this field is mandatory and the value of this field must be set. \n\nThis process overrides the value of `mandatory`.","INeonPropertyPlaceholderDataModel.placeholderProcess":"Process for a placeholder, will replace the `placeholder` property.","INeonPropertyContentTypeDataModel.contentTypeProcess":"Process that overrides the static `contentType` and calculates the value by using JDito.","INeonPropertyFormatDataModel.outputFormat":"Specifies the output format of the component. \n \nThe output can be formatted according to the type of the related database column, such as time and date values. \n\nThese can be set using a help editor.\n\n<!--EOF-->\n\nPlease note that some of the example values are only applicable for specific types in `contentType`.\n\nThe available special characters are the following:\n\n**For text values**\n\n* `#`: Any valid number, uses Character.isDigit.\n* `'`: Escape character, used to escape any of the special formatting characters.\n* `U`: Any character (Character.isLetter). All lowercase letters are mapped to upper case.\n* `L`: Any character (Character.isLetter). All upper case letters are mapped to lower case.\n* `A`: Any character or number (Character.isLetter or Character.isDigit)\n* `?`: Any character (Character.isLetter).\n* `*`: Anything.\n* `H`: Any hex character (0-9, a-f or A-F).\n\n**For number values**\n\n* `0`: number, digit, localised\n* `#`: number, Digit, zero shows as absent, localised\n* `.`: number, Decimal separator or monetary decimal, localised\n* `-`: number, Minus, localised\n* `,`: number, Grouping separator, localised\n* `E`: number, Separates mantissa and exponent in scientific notation. Need not be quoted in prefix or suffix, localised\n* `;`: Subpattern boundary, Separates positive and negative subpatterns, localised\n* `%`: pos, Multiply by 100 and show as percentage, localised\n* `‰`: pos, Multiply by 1000 and show as per mille, localised\n* `¤`: pos, Currency sign, replaced by currency symbol. If doubled, replaced by international currency symbol. If present in a pattern, the monetary decimal separator is used instead of the decimal separator. not localised\n* `€`: Currency symbol (euro)\n* `¥`: Currency symbol (yen)\n* `$`: Currency symbol (dollar)\n* `'`: prefix or suffix, Used to quote special characters in a prefix or suffix, for example, `' # '#` formats `123` to `\"#123`. To create a single quote itself, use two in a row: `\"# o''clock.\"\"`. not localised\n\n**For date values**\n\n| Letter | Date or Time component | Presentation      | Examples                              |\n|:------:|------------------------|-------------------|---------------------------------------|\n|  `G`   | Era designator         | text              | AD                                    | \n|  `y`   | Year                   | Year              | 1996; 96                              | \n|  `M`   | Month in year          | Month             | July; Jul; 07                         | \n|  `w`   | Week in year           | number            | 27                                    | \n|  `W`   | Week in month          | number            | 2                                     | \n|  `D`   | Day in year            | number            | 189                                   | \n|  `d`   | Day in month           | number            | 10                                    | \n|  `F`   | Day of week in month   | number            | 2                                     |\n|  `E`   | Day in week            | text              | Tuesday; Tue                          | \n|  `a`   | Am/pm marker           | text              | PM                                    | \n|  `H`   | Hour in day (0-23)     | number            | 0                                     | \n|  `h`   | Hour in day (1-24)     | number            | 24                                    | \n|  `K`   | Hour in am/pm (0-11)   | number            | 0                                     | \n|  `h`   | Hour in am/pm (1-12)   | number            | 12                                    | \n|  `m`   | Minute in hour         | number            | 30                                    | \n|  `s`   | Second in minute       | number            | 55                                    | \n|  `S`   | Millisecond            | number            | 978                                   | \n|  `z`   | Time zone              | General time zone | Pacific Standard Time; PST; GMT-08:00 | \n|  `Z`   | Time zone              | RFC 822 time zone | -0800                                 |","INeonPropertyContentTypeDataModel.htmlEditorFeatures":"Specifies what features should be available in the HTML editor.\n \n If set to `BASIC` the editor will only have the basic features such as font stylings.\n\n Whereas if set to `ADVANCED` the editor will have rich CMS features like creating tables and further styling options.","INeonPropertyContentTypeDataModel.ckeditorAIAssistantEnabled":"Determines whether the AI Assistant is active for this CKEditor instance.\nBehavior:\ntrue: enable the AI Assistant for this instance of the CKEditor (=default).\nfalse: disable the AI Assistant for this instance of the CKEditor.","INeonPropertyContentTypeDataModel.ckeditorAIAssistantEnabledProcess":"Determines whether the AI Assistant is active for this CKEditor instance. The process is only executed once during initialization of the CKEditor\ninstance and can be used to enable or disable the AI Assistant based on different conditions.\nOverwrites the ckeditorAIAssistantEnabled flag of the CKEditor instance.","INeonPropertyContentTypeDataModel.ckeditorAISystemPromptProcess":"Specifies a process that overwrites the default AI system prompt that is set in the ckeditorDefaultAISystemPromptProcess in the preferences.\nThe process should return a string that describes how the AI should behave.\nIf null is returned, then the default CKEditor prompt is used:\n\"Your task is to generate HTML content accordingly to the given instruction. Never include img tag in your response even if asked for.\nYour answer must be a well-structured and properly formatted HTML code. Answer only with the generated HTML content.\nDo not add any additional remarks or notes. Do not act like a chatbot or a real person.\"","INeonPropertyContentTypeDataModel.ckeditorAICommandsProcess":"Specifies a process that overwrites the default AI commands that are set in the ckeditorDefaultAICommandsProcess in the preferences If null is\nreturned, then no commands will be visible in the CKEditor. The process should return an array with JSON objects that contain the following\nproperties: e.g. [{ groupId: customGroupId, groupLabel: My group of commands,\ncommands: [ { id: translateSpanish, label: Translate to Spanish, prompt: Translate this text to Spanish. }, { id: explainFive, label: Explain like I'm five, prompt: Explain this like I'm five years old. } ] }]\nConsult the CKEditor Documentation for more information.","INeonPropertyContentTypeDataModel.mentionFeeds":"JSON structure, that determines the mentions shown in the CKEditor.\nNeeds to return an array of JSON objects containing a feed of tags.\n\n### Limitations:\n\nThe String can not exceed 5,000,000 characters, because of performance limitations.\n\n### Example:\n\n```javascript\nresult.string(JSON.stringify([\n\t{\n\t\tmarker: '@',\n\t\tfeed: [ '@Barney', '@Lily', '@Marry Ann', '@Marshall'],\n\t\tminimumCharacters: 1\n\t}\n]));\n```\n\nSee [CKEditor Mentions Documentation](https://ckeditor.com/docs/ckeditor5/latest/features/mentions.html#configuration) for further information","INeonPropertyContentTypeDataModel.filterTreeExcludedFieldsProcess":"Process that returns an array of EntityFieldNames that should be excluded when the FilterTree is shown.\n e.g. `result.object(['SUBJECT', 'INFO'])` will exclude these fields from the available filter fields.","INeonPropertyContentTypeDataModel.filterTreeIgnorePermissions":"If this setting is set to `true`, all existing permissions for the entity fields within the filter tree component are ignored.\ne.g. `PermissionDetail_entity`: The administrator should be able to open the filter tree for the entity field `CONDITION` and grant conditional permissions without having the permissions for the entity to be permitted.","INeonPropertyContentTypeDataModel.maxValue":"the maximum value","INeonPropertyContentTypeDataModel.maxValueProcess":"the process for the maximum value","INeonPropertyValueDataModel.onValueChange":"Process that is executed when the value of a field was changed. Will only trigger if the change was performed by a sources that is set in the `onValueChangeTypes` property.","INeonPropertyContentTypeDataModel.minValue":"the minimum value","INeonPropertyFormatDataModel.inputFormat":"Specifies the input format of the component.\n \nThe output can be formatted according to the type of the related database column, such as time and date values.\n\nThese can be set using a help editor.\n\n<!--EOF-->\n\nPlease note that some of the example values are only applicable for specific types in `contentType`.\n \nThe available special characters are the following:\n\n**For text values**\n\n* `#`: Any valid number, uses Character.isDigit.\n* `'`: Escape character, used to escape any of the special formatting characters.\n* `U`: Any character (Character.isLetter). All lowercase letters are mapped to upper case.\n* `L`: Any character (Character.isLetter). All upper case letters are mapped to lower case.\n* `A`: Any character or number (Character.isLetter or Character.isDigit)\n* `?`: Any character (Character.isLetter).\n* `*`: Anything.\n* `H`: Any hex character (0-9, a-f or A-F).\n\n**For number values**\n\n* `0`: number, digit, localised\n* `#`: number, Digit, zero shows as absent, localised\n* `.`: number, Decimal separator or monetary decimal, localised\n* `-`: number, Minus, localised\n* `,`: number, Grouping separator, localised\n* `E`: number, Separates mantissa and exponent in scientific notation. Need not be quoted in prefix or suffix, localised\n* `;`: Subpattern boundary, Separates positive and negative subpatterns, localised\n* `%`: pos, Multiply by 100 and show as percentage, localised\n* `‰`: pos, Multiply by 1000 and show as per mille, localised\n* `¤`: pos, Currency sign, replaced by currency symbol. If doubled, replaced by international currency symbol. If present in a pattern, the monetary decimal separator is used instead of the decimal separator. not localised\n* `€`: Currency symbol (euro)\n* `¥`: Currency symbol (yen)\n* `$`: Currency symbol (dollar)\n* `'`: prefix or suffix, Used to quote special characters in a prefix or suffix, for example, `' # '#` formats `123` to `\"#123`. To create a single quote itself, use two in a row: `\"# o''clock.\"\"`. not localised\n\n**For date values**\n\n| Letter | Date or Time component | Presentation      | Examples                              |\n|:------:|------------------------|-------------------|---------------------------------------|\n|  `G`   | Era designator         | text              | AD                                    | \n|  `y`   | Year                   | Year              | 1996; 96                              | \n|  `M`   | Month in year          | Month             | July; Jul; 07                         | \n|  `w`   | Week in year           | number            | 27                                    | \n|  `W`   | Week in month          | number            | 2                                     | \n|  `D`   | Day in year            | number            | 189                                   | \n|  `d`   | Day in month           | number            | 10                                    | \n|  `F`   | Day of week in month   | number            | 2                                     |\n|  `E`   | Day in week            | text              | Tuesday; Tue                          | \n|  `a`   | Am/pm marker           | text              | PM                                    | \n|  `H`   | Hour in day (0-23)     | number            | 0                                     | \n|  `h`   | Hour in day (1-24)     | number            | 24                                    | \n|  `K`   | Hour in am/pm (0-11)   | number            | 0                                     | \n|  `h`   | Hour in am/pm (1-12)   | number            | 12                                    | \n|  `m`   | Minute in hour         | number            | 30                                    | \n|  `s`   | Second in minute       | number            | 55                                    | \n|  `S`   | Millisecond            | number            | 978                                   | \n|  `z`   | Time zone              | General time zone | Pacific Standard Time; PST; GMT-08:00 | \n|  `Z`   | Time zone              | RFC 822 time zone | -0800                                 |","INeonPropertyValueDataModel.onValueChangeTypes":"## Value Change Sources for onValueChange Process\n\nSpecifies which value change sources will trigger the onValueChange process.\n\nThe following source types are available:\n\n### PROCESS\nChanges triggered by processes that return values in EntityFields (e.g., valueProcess)\n\n### PROCESS_SETVALUE\nChanges made programmatically through methods like:\n- `neon.setFieldValue(...)`\n- `neon.setFieldValues(...)`\n- `vars.set(\"$field...\")`\n\n### RECORD\nChanges that occur when loading data from the RecordContainer (applies when loading and mapping record data to entity model fields)\n\n### MASK\nChanges initiated through user interaction or system interfaces:\n- Direct user input via the web client UI\n- EntityAccess operations:\n    - EntityWebservice calls\n    - `writeEntity` operations (via JScriptEntities methods)","INeonPropertyContentTypeDataModel.minValueProcess":"the process for the minimum value","INeonPropertyValueDataModel.compareChangesWithRecordField":"Specifies whether a change should be detected if the value is different from the RecordField.\nIf the property is `false`, changes are only recognized if the new value differs from the value after initialization.","INeonPropertyFieldSizeDataModel.maxFieldSize":"Defines the maximum allowed character count for an entity field during data validation.\n\nThis property is used exclusively for data validation during editing (=`NEW`/`EDIT`-mode):\n- For standard text fields: limits the character count\n- For contentType `FILE` fields: limits the byte size\n\nValidation behavior:\n- If a field's content exceeds this maximum size, validation will fail\n- If this property is not specified, no maximum size limit will be applied during validation","INeonPropertyFieldSizeDataModel.maxIntegerDigits":"Defines the maximum number of integer digits allowed for numeric fields during validation.\n\nThis property is used exclusively for data validation during editing (=`NEW`/`EDIT`-mode) of fields with contentType `NUMBER`:\n- Integer digits are those that appear before the decimal separator\n- For example: in \"3.14\", the integer digit count is 1\n\nValidation Behavior:\n- If a numeric field contains more integer digits than this maximum, validation will fail\n- If this property is not specified, no limit on integer digits will be applied during validation","INeonPropertyFieldSizeDataModel.maxFractionDigits":"Defines the maximum number of fraction digits allowed for numeric fields during validation.\n\nThis property is used exclusively for data validation during editing (=`NEW`/`EDIT`-mode) of fields with contentType `NUMBER`:\n- Fraction digits are the decimal digits that appear after the decimal separator\n- For example: in \"3.14\", the fraction digit count is 2\n\nValidation behavior:\n- If a numeric field contains more fraction digits than this maximum, validation will fail\n- If this property is not specified, no limit on fraction digits will be applied during validation","INeonPropertyGroupableDataModel.groupable":"If the groupable property of a field is set, this field can be selected as a grouping in the filter.\n\nThis is only possible in views that support grouping - for example: Tree, TreeTable, Chart, Map.","INeonPropertyGroupableDataModel.preferredGroupOrder":"This property defines the preferred order of the groups. If `DISPLAYVALUE` is selected, but not available, then `VALUE` is used.","INeonPropertyLinkedContextDataModel.linkedContext":"This will create a reference from your field to another context. For example: If you've got a `ORGANISATION_ID` you may want to link to a context that contains organisations.\n \nThe reference is then used for example to create a link in the client to the given Context & Record (\"the Organisation with ID _xyz_\").\nWhen a linkedContext is set, a matching ID to the data record needs to be returned by the value/valueProcess of this entityField.\nE.g., linkedContext = \"Organisation\" value = \"UUID to the organisation record\"","INeonPropertyLinkedContextDataModel.linkedContextProcess":"Basically the same as the `linkedContext` property that can be calculated dynamically with a process. This is useful if you've got a field that could\n be linked to different contexts (in case A to a context \"Organisation\", in case B to a context \"Person\").\n This will overwrite the `linkedContext` property; return a context name with `result.string(...)`.","INeonPropertyConsumerDataModel.consumer":"Specify already existent consumers within this entity to define possibleValues for this field. For example a lookup-component will be available in the client to select a record.","INeonPropertyPossibleItemsDataModel.dropDownProcess":"With this process you can define the possible items for this field.\nA combobox will be available in the client to select a value.","INeonPropertyPossibleItemsDataModel.textInputAllowed":"This property enables the functionality for the user to enter an own value.","INeonPropertyDefaultActionDataModel.defaultAction":"When this process is set, a button is set to the respective GUI component, which executes the process stored here when clicked.","EntityFieldGroupDataModel.valueProcess":"Formula.\n\nErrors that occur in this process are not passed to the client. These can only be found in the server log / log files.\n\nError messages from this process do not arrive at the client, they are only visible in the server log.","EntityFieldGroupDataModel.fields":"A list of fields that are included in this field group.","EntityProviderDataModel.children":"list of parameters in this provider","INeonPropertyTitlePluralProcessDataModel.titlePluralProcess":"Determine the title plural via a process; e.g. Persons\n \nThis is used within the client in views where multiple records are displayed - for example as detail-headline in a master-detail layout","EntityProviderDataModel.targetContextField":"Defines an entity-field that provides the name of a context.\nWhenever a context is needed, this newly provided context is then used instead of the entities context where your provider is located.\n\nThis is for example helpful if you have a generic link-entity where a \"foo\"- and a \"bar\"-context (+entity) can be linked.\nSince you do not want to display the preview of the generic link-context but the preview of each linked element you can specify a field here where\nthe matching context (either \"foo\" or \"bar\") is returned.","EntityProviderDataModel.targetIdField":"Defines an entity-field that provides the UID-value of another entity.\n\nThis is for example helpful if you have a generic link-entity where a \"foo\"- and a \"bar\"-context (+entity) can be linked.\nYou should've set already the `targetContextField` but there is need to determine the corresponding UID to the `foo_Entity`/`bar_Entity`.\n(When not setting this `targetIdField` the UID of the generic link-entity is used)","EntityProviderDataModel.targetConsumerProcess":"Process where the name of a consumer has to be returned.\n\nWhen requesting this provider the request is directly rerouted to the returned targetConsumer instead.","EntityProviderDataModel.useAggregates":"Determines whether the provider should aggregate all records and calculate only the aggregate fields.\n\nYou get one record with the aggregated fields only","EntityProviderDataModel.sortingField":"Select a sorting field for the provider to activate the sorting.\nThe current position of the data record is saved in the sorting field via a number.\nIf the provider is used in a GenericMultipleViewtemplate, arrows appear automatically for sorting the data records.\nThe sorting field is also used when loading the data records.","EntityProviderDataModel.sortingMethod":"Specifies which sorting method should be used if a `sortingField` was selected.\n\n* `NUMERIC` (default): data records are sorted by a numerical value. Due to performance concerns numerical sorting is currently not supported by Tree and TreeTable components.\n* `LEXORANK`: data records are sorted by the LexoRank algorithm which is represented by a string value. When choosing this method the initial ranks and the rebalancing of ranks needs to be handled manually. A suggested initial rank for the first row should be `lexorank.middle()`. The LexoRank method is currently only supported by Tree and TreeTable components and only when a single row is dragged and dropped.","EntityProviderDataModel.maxLexoRankLength":"Determines the maximum length of a LexoRank. This number should reflect the size of your db field. It is recommended to use a default size of 255 characters.\n\nIf the maximum rank length is reached for a row then reordering will be disabled and a rebalancing should be done.","EntityProviderDataModel.lookupIdfield":"Defines for a provider an (optional) alternate ID field. To identify a record, normally the UID of the entity is used.\n\nIn some cases you do not want to have the UID but another field as Key-Element. Therefor this field can be set.\nMain use case: Lookup-element that shall return a differing ID-field for easier handling within the consuming entity.","EntityProviderDataModel.uniqueProviderKeyProcess":"Process which returns a unique key for this provider. The key will be used to differentiate between the parents. The main use-case is to provide a separate last/saved/default filter for each key.\n\nExample: You have Context A, which defines a Provider. Context B consumes the Provider of Context A using a Consumer.\nBy default, you'd get the same last/saved/default filters for each record of Context A. But if you use the UID of the current record of Context B as your \"unique provider key\" you can provide a different last/saved/default filter.","IFilterVariablesContainerDataModel.filterVariablesProcess":"Process to extend the list of filterable items that are an additional option to choose a value from.\n\nThe result of the `filterVariablesProcess` must be an object that contains an arbitrary number of key-value pairs, where the key is the name of a variable whose value is to be used (not the value of the variable) and the value is the display value to be used in the client.\n\nThe variables value is resolved during runtime. \n\nExample that will add the item to filter for a value `Me` whenever this provider is used:\n\n```js\nimport(\"system.translate\");\nimport(\"system.result\")\n\nvar res = {\n\t\"global.user.contactId\": translate.text(\"Me\")\n};\n\nresult.object(res);\n```\n\nDuring runtime the parameter `$global.user.contactId` is resolved to its current value and replaced when filtering the data.\n\nThis enables the user to share a filter (for example in a dashlet) without containing the actual value for `Me` and thus resulting in a dynamic filter.","EntityProviderDataModel.initFilterMergeMode":"Determine whether a passed external filter should be automatically `AND` or `OR` linked with the entity's initFilter.\nThe `IGNORE` mode means that the filters are not automatically linked.\nThe external init filter can then be reacted to in the initFilterProcess. The filter can be obtained from the local variable `$local.filter`.","EntityParameterDataModel.title":"Singular title of this parameter, e.g. Person","EntityParameterDataModel.valueProcess":"Process that is executed when the value of the parameter is requested. In this process, everything can be returned.","EntityParameterDataModel.expose":"Indicates whether the parameter can be overridden by a dependency field, or whether it exists only in its own entity.","EntityParameterDataModel.mandatory":"Indicates whether this field is mandatory and the value of this field must be set.","EntityWebserviceDataModel.webserviceMethods":"HTTP methods supported by the web service","EntityWebserviceDataModel.loginTypeId":"Allows anonymous authentication for Web services.\n\nThis is where a login type is specified, which is specified in the instance config under `Client->Login` in the `loginList`.","EntityWebserviceDataModel.jditoWebserviceUser":"The title of the user under whose name the webservice is executed, this will affect both the user used for executing JDito and the\nevaluation of permissions. If specified, it will overwrite the login user. A value must be provided if the webservice can be accessed anonymously.","EntityWebserviceDataModel.restrictedRoles":"Only users with the specified roles can run the WebService. If no roles are specified here, all of them are allowed to access this webservice","EntityWebserviceDataModel.webserviceFields":"Entity fields that are made available in the web service","EntityWebserviceDataModel.writeProvider":"Provider used to write the entities","EntityWebserviceDataModel.readProvider":"Provider used to read the entities","EntityWebserviceDataModel.formEnabled":"Enables the form api for this entity webservice","EntityWebserviceDataModel.locale":"Specifies the default locale settings (language) for the entity webservice","EntityWebserviceDataModel.timezone":"The default timezone of the entity webservice","INeonPropertyDevicesDataModel.devices":"Determines on wich devices the component should be available.\n\nThe default value states that the component is available on all devices.\nIf one or more devices are selected then the component is only available for those selected devices.","WebserviceReferenceDataModel.entityField":"The field on which the referenced webservice is working. #ENTITY is your own entity","WebserviceReferenceDataModel.webservice":"Webservice that is referenced and displayed","ServiceImplementationDataModel.process":"Main process of the service implementation","NeonTableColumnDataModel.entityField":"The field on which the component is working.","INeonAggregatableColumnDataModel.aggregateEntityField":"The corresponding aggregate entity field for the given entity field.","INeonPropertyFullWidthDataModel.fullWidth":"Enable the option to display columns in full width","NeonDashletCategoryDataModel.title":"The title of the category to be displayed, e.g. \\\"Social Media\\\", \\\"Twitter\\\", \\\"Evaluations\\\"","NeonDashletConfigurationDataModel.title":"Singular title of the dashlet configuration","NeonDashletConfigurationDataModel.description":"Description","NeonDashletConfigurationDataModel.fragment":"Predefined URL fragment, which is passed on to the linked view. Useful for filter tables, whose search condition is passed on by the URL.\nThis could be for example in a filter_view: `{{nameofContext}}/filter` like `Activity/filter`.","NeonDashletConfigurationDataModel.preview":"Preview picture that is shown for example in the dashletstore as base64-encoded string","NeonDashletConfigurationDataModel.singleton":"Flag, determining if the dashlet can be active only once at a time (per user). \nSo a singleton dashlet cannot exist twice or more within one dashboard.","NeonDashletConfigurationDataModel.fragmentCustomizable":"Flag, determining if the URL fragment can be editied by users","NeonDashletConfigurationDataModel.requiresConfiguration":"Flag, determining if the dashlet has to be configured by the user to work properly. If so, the user is asked to configure it when adding the dashlet.","NeonDashletConfigurationDataModel.categories":"Categories of the dashlet configuration. These categories are used to group information for example in the dashlet-store.\nA dashlet can have several categories at the same time (1:n)","NeonDashletConfigurationDataModel.parameters":"Allows to specify values for parameters (params are defined in the linked entity). Note that you do not have access to any code/variables.\nIt's only possible to specify hard-coded values there.\n\nExample: If you want to limit records to those wo were created by the current logged-in user, it's possible to add a param `filterCreatedByMe_param` in the entity, limit the data in the recordContainer whenever the param is `true` and then specify in the `parameters`-config of the dashlet the value of `filterCreatedByMe_param` as `true`.","NeonDashletConfigurationDataModel.storeRoles":"Names of the roles, which have access to the configuration in the dashletstore","NeonDashletConfigurationDataModel.provider":"Set a specific entity provider for the dashlet to load the data","NeonDashletDataModel.viewName":"Name of the view that is linked with the dashlet","NeonDashletDataModel.configName":"Name of the configuration that exists within the linked view (see `viewName`)","NeonDashletDataModel.title":"Displayed title of the dashlet. The title is used for example when the user loads a dashboard for the first time as a preset value.","NeonDashletDataModel.requiresConfiguration":"Flag, determining if the dashlet has to be configured by the user to work properly. If so, the user is asked to configure it when adding the dashlet.","NeonDashletDataModel.parameters":"Allows to specify values for parameters (params are defined in the linked entity). Note that you do not have access to any code/variables.\nIt's only possible to specify hard-coded values there.\n\nExample: If you want to limit records to those wo were created by the current logged-in user, it's possible to add a param\n`filterCreatedByMe_param` in the entity, limit the data in the recordContainer whenever the param is `true` and then specify in the\n`parameters`-config of the dashlet the value of `filterCreatedByMe_param` as `true`.","NeonDashletDataModel.uiConfiguration":"Linked UI configuration of the dashlet (like position, size, etc.)","NeonDashletParameterDataModel.value":"The parameter value","NeonDashletUIConfigurationDataModel.xPos":"X position of the dashlet","NeonDashletUIConfigurationDataModel.yPos":"Y position of the dashlet","NeonDashletUIConfigurationDataModel.colspan":"width of the dashlet","NeonDashletUIConfigurationDataModel.rowspan":"height of the dashlet","BoxLayoutDataModel.direction":"Defines the direction of the Items in the Boxlayout e.g Horizontal / Vertical.\nThis is always set to Vertical on mobile devices","BoxLayoutDataModel.maxDirectionElements":"Defines the maximum amount of items per direction e.g. 3 items each row / column.\nIf there are more items in the Layout than maxDirectionElements is set to then the remaining items will be Wrapped into a new row / column (depending on the direction)","BoxLayoutDataModel.autoHeight":"Flag if the Layout should determine its height automatically.\nThe automatic layout height is calculated by the height of its components.","DrawerLayoutDataModel.layoutCaption":"Title of the drawer that is displayed within the top of the drawer to describe what information is shown within the drawer element.\nThis could be e.g. \"Activity\" to describe that the following content in the client is something about an \"activity\".","DrawerLayoutDataModel.layoutCaptionProcess":"This process is used to dynamically set the title of the drawer.\nIf this process isn't used or returns null then \"layoutCaption\" will be used.\n\n\nBecause of UX reasons you should use following format if you're using the process to display dependencies between tables:\n\n`tablename - dependencyTitle1: dependecyItem1 | dependencyTitle2: dependencyItem2`\n\nFor Example:\n\n```text\nOrganisation\nOffer - Organisation: Tree Inc.\nOffer Items - Organisation: Tree Inc. | Offer: 1019-1\n```","DrawerLayoutDataModel.fixedDrawer":"Determines if the drawer is fixed or not. A fixed drawer cannot be collapsed (and after that: expanded)","GridLayoutDataModel.columnCount":"Defines the amount of columns that should be displayed in the grid layout.\nMobile devices will always use only one column and ignore this option.","GridLayoutDataModel.rowCount":"Defines the amount of rows that should be display in the grid layout.\nBy default, the amount of rows is calculated automatically and should only be explicitly set in combination with a custom row height.","GridLayoutDataModel.rowHeight":"Defines the height in px that each row should have.\nBy default, each rows height is 1fr (for more information consult the MDN web docs section about grid layout) and should only be changed if a custom row count is set.","HeaderFooterLayoutDataModel.header":"The view that should be shown as the header view of the layout.\nA header view is always visible and is positioned above the scrollable content area of the layout.","HeaderFooterLayoutDataModel.footer":"The view that should be shown as the footer view of the layout.\nA footer view is always visible and is positioned below the scrollable content area of the layout.","MasterSlaveLayoutDataModel.master":"Determines which view is used as the master view. The master view represents the main element that contains the most important information while there may be several detail elements which contain more specific information.","INeonComponentEntityFieldDataModel.entityField":"This property is mandatory. Its value must be set to\n1. `#ENTITY`, when the ViewTemplate uses multiple EntityFields of the Entity belonging to the View (default).\n2. a single EntityField, if the ViewTemplate uses only this one single EntityField (example: WebContentViewTemplate).\n\nThe second option will result in a performance optimization.","IDatalessRecordContainerDataModel.alias":"The database alias that is used by this recordcontainer.","IDBRecordContainerDataModel.alias":"The database alias that is associated with this recordcontainer","IDBRecordContainerDataModel.linkInformation":"Specifies the links to the database. The `linkInformation` determines which data the core will fetch at a select and which table columns can be linked to components on the recordcontainer. Only tables that are in the alias associated with the recordcontainer can be specified here. \n\nIn the first place, the link information should be the primary key table of the recordcontainer, a table whose IDs do not appear twice. The `linkInformation` affects the select and the sorting of the recordcontainer, the index, as well as the automatic addition, modification and deletion of linked data records (e.g., relation record in the company).","ICacheRecordContainerDataModel.cacheType":"Defines the type for the caching of this record container. If no `cacheType` is selected, it will default to `NONE` and no cache will be used for this record container.\n\n* `NONE`: Caching is disabled for this record container.\n* `GLOBAL`: A global cache store for all users on the current server will be used for this record container.\n* `SESSION`: A cache store which is scoped to the current user will be used for this record container.","ICacheRecordContainerDataModel.cacheKeyProcess":"Process that will return the computed cache key for the given cache request. The cache request is defined through the given local variables. It's expected to return a string, which acts as a unique key for the cache request.\nIf `null` is returned, the current cache request will never be cached.","IDBRecordContainerDataModel.maximumDbRows":"Specifies the maximum number of items to display during a search. If this number is set to `0`, all elements are loaded and a different number is used as the maximum number.","IDBRecordContainerDataModel.isPageable":"Determines whether the record container should load the data blockwise or deliver them all at once.","IDBRecordContainerDataModel.minimizeCountQueries":"When `true`, the recordContainer will perform less `SELECT COUNT(*)...`-queries and determine the count instead based on the\nloaded data.\nHowever, this may lead to different count results as a `SELECT COUNT(*)...`-query under certain circumstances. \n\nThis is a tradeoff of being faster due to less time-consuming queries, however some display values may not be as accurate.\nEnabling `minimizeCountRequests` will also affect the `$local.datarowcountfull`-variable. \n\nExample when the recordContainer populates data of a ViewTemplate (table):\n\nThe RecordContainer is limited to 200 records (see `maximumDbRows`), while there exist 456 records in the database.\n\nWhen `minimizeCountRequests` is `true`, the display value of the record-amount will be 200 and the `$local.datarowcountfull`-variable has the value `\"200\"`. \n\n→ It is impossible for the recordContainer to know the full count when no additional count query is performed.\nWhen `minimizeCountRequests` is `false`, the display value of the record-amount will be 456 and the `$local.datarowcountfull`-variable has the value `\"456\"`.\n\n→ Thanks to the additional count-query, the recordContainer knows the full count of records and other modules (like the ViewTemplate) can use\nthis information to display the overall full count.","IDBRecordContainerDataModel.supportsFilterExtensionGrouping":"This will enable filterExtensions even on non-pageable RecordContainers for grouping.\nBe aware of the consequences of enabling the support of filterExtensions (and filterExtensionSets):\nThis will result in several queries for the recordContainer when grouped by a filterExtension (each group and entry will be an extra query).\nThis will have an impact to the performance of loading the data (all data will be loaded).\n\nIn a DB-RecordContainer nothing more has to be done here.","IDBRecordContainerDataModel.isReadOnly":"Records of the record container can only be read. No data can be saved or deleted","IDBRecordContainerDataModel.isRequireContainerFiltering":"Forces a filtering of the records via the record container. No client-side filtering is possible.","IDBRecordContainerDataModel.hasDependentRecords":"If your records are interdependent, for example in a parent-child structure for trees, you should use this flag. This has effects when deleting records because now the data structure is always rebuilt → a refresh is triggered after deletion.","IDBRecordContainerDataModel.fromClauseProcess":"Can be used to specify a custom fromClause statement for the tables configured in the linkInformation, which is usually necessary when there are \nmultiple tables that have to be joined.\nIf nothing is specified here, all tables specified in the **linkInformation** are used (cross join).\nIt is possible to specify different fromClauses for the count query and data query by using the local variable `$local.isCount`,\nwhich contains a boolean value that is `true` for the count query and `false` for the data query.","IDBRecordContainerDataModel.conditionProcess":"Condition that is applied to all database queries. It is appended with \\\"and\\\" to the original queries.","IDBRecordContainerDataModel.orderClauseProcess":"Returns a map that specifies how the columns are to be ordered. This map is structured as follows:\n\n* Key = column name\n* Value = Boolean that indicates whether the data should be sorted descending (`true` = desc, `false` = asc). If no value is specified, ascending is sorted.","IDBRecordContainerDataModel.onDBInsert":"Process that runs when an entry is saved to the database.\n\nAs localvar, `$local.uid` (value of the ID column) and `$local.rowdata` (entry as JSON) are available here.\n\nIt is not possible to return values from this process.","IDBRecordContainerDataModel.onDBUpdate":"Process that is executed when an entry in the database is updated.\n\nAs localvar, `$local.uid` (value of the ID column) and `$local.rowdata` (entry as JSON) are available here.\n\nIt is not possible to return values from this process.","IDBRecordContainerDataModel.onDBDelete":"Process that is executed when an entry in the database is deleted. As localvar, `$local.uid` (value of the ID column) and `$local.rowdata` (entry as JSON) are available here.\n\nIt is not possible to return values from this process.","IIndexRecordContainerDataModel.indexFieldMappings":"Specifies the list of record fields for the entity that are included in the index.\n\nThe first three entries are always the three system fields `#UID`, `#TITLE` and `#DESCRIPTION`.\n\nEntries for other system fields and entries for `.value` and `.displayValue` for each entity field can be added.","IIndexRecordContainerDataModel.configMode":"Specifies the type of configuration for this record container.\n\n* `INDEXGROUP_DEFINITION`: The record container is used by the indexer to create an index group and allows the fields and contents to be configured accordingly. This will use the properties in the `IndexGroup`, `Indexsearch` and `IndexBuilder` elements for further configuration.\n* `READ_ONLY`: The record container only has read access to the index and supplies content based on other index groups. This will use the properties in the `Search` element for further configuration.","IIndexRecordContainerDataModel.patternExtensionProcess":"Provides an extension of the pattern of the index search.\n\nThis supplied pattern is then associated with \"and\" with the original pattern.\n\nThese localvar are available here: \n* `$local.pattern` - the original pattern\n* `$local.locale` - the language of the user as locale, e.g. \"De_DE\"\n* `$local.indexgroupId` - group to be searched, cf. `indexGroup`","IIndexRecordContainerDataModel.boostPatternProcess":"Provides a boost pattern for the index search.","IIndexRecordContainerDataModel.searchIndexGroups":"The identifier of the index groups that are searched by this record container","IIndexRecordContainerDataModel.isActive":"Indicates whether the record container should be used.\n\nIf it is deactivated (`false`), it is not indexed and can neither be used by the record container nor by the global search.","IIndexRecordContainerDataModel.isGlobal":"Specifies whether the index group of this record container should be included in the global search (user search).","IIndexRecordContainerDataModel.indexRecordAlias":"Alias on which the processes of this index record field is executed.","IIndexRecordContainerDataModel.indexGlobalTags":"Specifies whether all global tags (`#`) for the index group should be indexed automatically.\n\n**NOTE:** It set to true, the corresponding system field `#TAG` of the index does not have to be included in the list of `indexFieldMappings`.\n\n**WARNING:** All values for hashtags that are set directly via the SQL of the query property overwrite all values that are loaded via this flag.","IIndexRecordContainerDataModel.query":"Process that generates the SQL query that is used by the indexer to create the index group.\n\nThe columns in the `SELECT` **must** match the order and number of the entries specified in the `recordFieldMappings`.","IIndexRecordContainerDataModel.subProcess":"Process which is executed once per data record of the SQL SELECT and which allows the entries to be overwritten or changed.\n\n**IMPORTANT:** It is advised to reduce ressource heavy executions (e.g. `entities.get*`) to a minimum as it can have major negative performance impact as this processes will be called for every document!","IIndexRecordContainerDataModel.affectedTables":"Defines the tables whose changes (via DB audit) are evaluated by the incremental indexer in order to check them for relevant changes for the index.\n\nThe actual check is done by the process `affectedIds`.","IIndexRecordContainerDataModel.affectedIds":"Process that evaluates the database audit events.\nThis process is used to determine whether a change is relevant for the index and whether the data record in the index needs to be updated.\nAs a result, a list with the UIDs of the changed entries is expected.","IJDitoRecordContainerDataModel.jDitoRecordAlias":"Alias on which the processes of this JDito records field are executed.","IJDitoRecordContainerDataModel.recordFieldMappings":"Mapping that determines how the data of the JDito recordContainer is linked to the entity-fields.\nExample: If you return in the contentProcess per row 5 columns of data (=an array that contains arrays with 5 elements) you have to specify in the recordFieldMapping 5 entity-fields where the value of the respective row are mapped.\n\nThis means: You need to specify the correct amount and order of fields in the mapping.","IJDitoRecordContainerDataModel.aggregateFieldMappings":"Mapping of aggregateFields of the JDITO recordContainer\n\nUsage see: recordFieldMappings","IJDitoRecordContainerDataModel.isPageable":"Determines if the recordContainer \"knows\" how to process data blockwise or not. Since you can do in the JDito-record-container everything you want, you need to implement paging yourself. Therefor, you get extra `$local`-variables in the contentProcess.","IJDitoRecordContainerDataModel.supportsFilterExtensionGrouping":"This will enable filterExtensions even on non-pageable RecordContainers for grouping.\nBe aware of the consequences of enabling the support of filterExtensions (and filterExtensionSets):\nThis will result in several queries for the recordContainer when grouped by a filterExtension (each group and entry will be an extra query).\nThis will have an impact to the performance of loading the data (all data will be loaded).\n\nIn a JDito-RecordContainer the grouping needs to be implemented, see the `isGroupable` property for details on how to implement group-rows.","IJDitoRecordContainerDataModel.isFilterable":"Determines if the recordContainer \"knows\" how to filter data or not. Since you can do in the JDito-record-container everything you want, you need to implement applying a filter yourself. Therefor, you get extra `$local`-variables in the contentProcess.","IJDitoRecordContainerDataModel.isGroupable":"Determines if the recordContainer is able to group data or not. Since you can do in the JDito-record-container everything you want, you need to implement applying a group yourself. Therefor, you get extra `$local`-variables in the contentProcess.\nIf `isGroupable` is not set, the client does the grouping. This means that the RecordContainer does not have to implement any logic for groupings.\nIf `isGroupable` is set, grouping logic must be implemented. Various `$local` variables are available to make this easier.\n\n* `$local.grouped`: Contains the current grouping. This variable only exists if there is a grouping. If `$local.grouped` is set, the following three fields must be placed in front of the result array in the ContentProcess of the RecordContainer in this order: \n\t\n\t1. childCount\n\t2. groupValue\n\t3. groupTitle\n\n* `$local.startrow`: Contains the start index of entries to be loaded.\n* `$local.pagesize`: Contains the maximum number of entries which can be returned\n* `$local.order`: Contains the fields and the corresponding order as a map in the following format: e.g. `ATTRIBUTE_TYPE.displayValue` -> `UP`\n* `$local.filter`: Contains the filter properties as a map with the following entries: `filter`, `permissions`, `subset`, `ids`, `excludedIds`\n* `$local.filters`: Contains all filter properties as a search condition in form of a JSON\n* `$local.userfilter`: Contains `vars.get(\"$local.filter\").filter`; as a search condition in form of a JSON\n* `$local.idvalues`: Contains the IDs which are loaded as a String array\n* `$local.idvaluesExcluded`: Contains the IDs which are excluded when loading the data\n* `$local.fieldhints`: Contains a map with two entries - aggregateFields in form of an array and recordFields in form of an array","IJDitoRecordContainerDataModel.isRequireContainerFiltering":"In some situations (for example searching in a lookup component on a not pageable recordContainer), filtering is then done on clientSide.\nIf you want to prevent filtering on the clientSide (which is very reasonable from a performance perspective) you can force with this property(=`true`) that filtering shall always be done by the recordContainer.","IJDitoRecordContainerDataModel.isSortable":"Determines if the recordContainer \"knows\" how to sort data or not. Since you can do in the JDito-record-container everything you want, you need to implement sorting mechanisms yourself. Therefor, you get extra `$local`-variables in the contentProcess.","IJDitoRecordContainerDataModel.contentProcess":"Process that has to return the current content; return a 2D-array via `result.object(...)`.\nThere are - depending on configured properties - a lot of `$local`-variables that might be set which you should handle in your `contentProcess`.\nFor example the `$local.idvalues` variable is very important when it comes to reloading specific records.","IJDitoRecordContainerDataModel.rowCountProcess":"Process that has to return the current amount of records. Whenever possible you should implement this process to increase performance of the system.\nThis is because in certain situations the amount of records is needed and if you do determine the amount of records the system needs to call the `contentProcess` only to get the count of elements.\nIf you're able to determine the amount of records faster and with less resources you should do this in this process so that only this process needs to be called for determining the count of records.","IJDitoRecordContainerDataModel.hasDependentRecords":"If your records are interdependent, for example in a parent-child structure for trees, you should use this flag. This has effects when deleting records because now the data structure is always rebuilt => a refresh is triggered after deletion.","IJDitoRecordContainerDataModel.onInsert":"Process that is executed when a record is to be stored in the JDito.\n\nAs localvar, `$local.uid` (ID of the record) and `$local.rowdata` (entry as JSON) are available here. \n\nIt is not possible to return values from this process.","IJDitoRecordContainerDataModel.onUpdate":"Process that is executed when a record is to be updated in the JDito.\n\nAs localvar, `$local.uid` (ID of the record) and `$local.rowdata` (entry as JSON) are available here. \n\nIt is not possible to return values from this process.","IJDitoRecordContainerDataModel.onDelete":"Process that is executed when a record is to be deleted in the JDito.\n\nAs localvar, `$local.uid` (value of the ID column) and `$local.rowdata` (entry as JSON)\nare available here.\n\nIt is not possible to return values from this process.","INeonPropertyFilterableDataModel.isFilterable":"Specifies, whether a field or filterextension is filterable. Filterable fields will be available for selection by a user.","AggregateFieldDBMappingDataModel.aggregateType":"the aggregate type of the field","INeonPropertyFilterableDataModel.isLookupFilter":"For a column of the lookup component, specifies whether to search for data in it.\nThat is, if a term is entered in the lookup component, it searches for matches in all columns marked as `isFilterable`.","DBRecordFieldMappingDataModel.recordfield":"Database column that provides the values of the corresponding EntityField.\nThe value of this property will be included in the generated SQL select statement.\n\nIf both properties `recordfield` and `expression` are set, only `expression` will be executed.","DBRecordFieldMappingDataModel.expression":"Process that returns an SQL expression that will be used in the generated select statement (instead of the record field). Often this is a subselect or a case-when statement.\nYou do not need to specify surrounding brackets - this is done automatically.\n\nIf both properties `recordfield` and `expression` are set, only `expression` will be executed.\n\nIf you want to refer to this expression in other parts of the SQL code (e.g., in an `orderClauseProcess`), you should set and use property `columnAlias`.","DBRecordFieldMappingDataModel.columnAlias":"SQL alias used for recordfield / expression in the generated select statement (e.g. `recordfield AS columnAlias`).\n\nIn particular, with this property you are able to simplify references to complex `expression` subselects in other parts of the generated SQL code (e.g., in an `orderClauseProcess`).","INeonPropertyFiltertypeDataModel.filtertype":"Delivers a hint, to which filter this field(s) should be added","ConsumerMappingDataModel.filterConditionProcess":"To activate the automatic filtering via a consumer, it is necessary to supply a condition.\nThe condition have to filter the data records linked via the consumer based on the filter criterion set by the user.","FilterExtensionDataModel.title":"Title of additional field.","IFilterExtensionDataModel.isFilterable":"Boolean flag for indicating, if this field is filterable","IFilterExtensionDataModel.isLookupFilter":"Delivers a hint, if this filter is a lookup to an other context","FilterExtensionDataModel.contentType":"ContentType of additional field.","FilterExtensionDataModel.useConsumer":"Boolean flag for indicating, if this filter extension should use a consumer to select a value (instead of the `filterValuesProcess`)","FilterExtensionDataModel.consumer":"Specify already existent consumers within this entity to define possibleValues for this filter extension.\nA lookup-component will be available in the client to select a record.\n\n<!--EOF-->\n\nThis element is only used if `useConsumer` is set to `true`.","FilterExtensionDataModel.filterValuesProcess":"This process delivers possible values for this field.\n\n<!--EOF-->\n\nThis element is only used if `useConsumer` is set to `false`.","FilterExtensionDataModel.filterConditionProcess":"This process delivers a condition, which will be used to obtain the recordset","FilterExtensionDataModel.groupedRecordField":"Recordfield which will be used for grouping","FilterExtensionDataModel.titleRecordField":"Recordfield, which contains the title of a group","IFilterExtensionDataModel.isGroupable":"If the `groupable` property of a field is set, this field can be selected as a grouping in the filter, but only if the RecordContainer is pageable.\nThis is only possible in views that support grouping - for example: Tree, TreeTable, Chart, Map.","IFilterExtensionDataModel.groupQueryProcess":"This process has to return a SQL query as string for obtaining the list of groups.\nVarious `$local` variables are available to make this easier.\n\n* `$local.name`: Contains the full name in the following format: entityName.fieldName\n* `$local.fieldname`: Contains the fieldName\n* `$local.contenttype`: Contains the type of the field, e.g. `TEXT`, `NUMBER`, `IMAGE`, `BOOLEAN`, ...\n* `$local.columntype`: Contains the generic SQL type, e.g. `VARCHAR`, `NUMERIC`, `BINARY`, `TIMESTAMP`, ...\n* `$local.count`: Contains a boolean which is true, if only the number of records is required. If this property is true the data can be ignored. Only the number of records must be correct.\n* `$local.columns`: Contains the columns of a table which are required as string array.\n* `$local.columnlist`: Contains the columns of a table which are required in a comma separated list. Can never be null, only empty list.\n* `$local.condition`: Contains the where-clause of an SQL as string.\n* `$local.grouped`: Contains the current grouping in form of an array.\n* `$local.groupedList`: Contains the current grouping as comma separated list.\n* `$local.order`: Contains the fields and the corresponding order as a map in the following format: e.g. `ATTRIBUTE_TYPE.displayValue` -> `UP`","FilterExtensionSetDataModel.filterFieldsProcess":"This process delivers a list of fields, which can be used to extend options for filtering or grouping.\nThis process has to return an array of objects with the following parameters:\n\n* `name`: unique identifier\n* `title`: (unique) title\n* `contentType`: content type of the filter field, e.g. `TEXT`\n* `hasDropDownValues`: if true uses the return values of the filterValueProcess as possible filter values\n* `isFilterable`: if true the field is shown in the filter fields\n* `isGroupable`: if true the field is shown in the groupable fields\n* `groupedRecordField`: the corresponding record field in the database, e.g. `ID_VALUE`\n* `titleRecordField`: expects a SQL statement which contains the grouping title. If this parameter is empty, the value of the `groupedRecordField` is used as title.\n* `consumer`: expects the name of the consumer as string. If this parameter is set, instead of using the `filterValuesProcess`, the values returned by the `consumer` are used as possible filter values.","FilterExtensionSetDataModel.filterValuesProcess":"This process delivers possible values for this field.","FilterExtensionSetDataModel.filterConditionProcess":"This process delivers a condition, which will be used to obtain the recordset","IndexRecordFieldMappingDataModel.systemField":"Defines the system field of the index to which this field is mapped.","IndexRecordFieldMappingDataModel.indexFieldType":"Defines the type of index field used by this field.\n\nThe field type specifies how the field should be indexed.\nDepending on the type, the input values are evaluated differently by the index, which has a major influence on the search.","IndexRecordFieldMappingDataModel.additionalFieldNameAliases":"Adds one or more additional names (aliases) to the field for the search. \n\nThe field can then be searched for in the global search or directly with this name via JDito. Several fields, independent of the actual group, can have the same alias. \n\nFor example if `Person` and `Organisation` specify two different fields that both have the alias `name`, both fields are searched when using the pattern `name:a*`.","IndexRecordFieldMappingDataModel.isIndexed":"Specifies if the content of this field should be indexed.\n\nIf deactivated the field is **not** searchable.\n\n**NOTE:** If a field has neither the `indexed` nor `stored` properties, it is not included in the index.","IndexRecordFieldMappingDataModel.isStored":"Specifies if the original content of this field should be stored in the index.\n\nIf deactivated the field is searchable, but the value is not contained in the result of a search.\n\n**NOTE:** If a field has neither the `indexed` nor `stored` properties, it is not included in the index.","IndexRecordFieldMappingDataModel.isMultiValued":"Specifies if the field can contain multiple values for one entry.\n\nOnly use this property if a record for this field actually can contain multiple values.\n\nIf stored all values are returned in the result.","IndexRecordFieldMappingDataModel.isBoosted":"Marks this field as more important for the search.\n\nAll values for fields marked as `boosted` are written in a special system field in the document,\nthat will rank all hits higher for exact matches (by word).","IndexRecordFieldMappingDataModel.isGlobalSearchField":"Specifies if this field should be included in the global search.\n\nIf deactivated this field can still be searched when specified directly via name,\nbut it will no longer be searched if no search fields are specified.","IndexRecordMultilingualSystemFieldMappingDataModel.isMultiLanguage":"Specifies if the index field is multilingual.\n\nThe index only uses the languages that are specified in the property `multilingualismIndexSearchLocales` of `___CONFIGURATION`.","IndexRecordMultilingualSystemFieldMappingDataModel.translationMode":"Specifies the method with which the values of the field are translated.\n\n* `INTERN`: Directly uses the project's language packs for the translation. The original value of the field is used as the key.\n* `STATIC`: Uses a static mapping for the translation, which is set up via the `mappingProcess`. This option is mainly intended for the translation of keywords and values that are as unique as possible. **IMPORTANT:** The created mapping is kept in the RAM during the entire indexing process. Large amounts of values and large field contents can lead to a memory overflow.\n* `DYNAMIC`: Uses the specified `translationProcess` for the translation. **IMPORTANT:** This option can have a major negative impact on the speed of indexing. The process is called once for each entry in the field for each language for each index document. Reduce ressource heavy executions (e.g. `entities.get*`) to a minimum.\n\nAll translation methods are ignored if a `templateProcess` is defined for the field.","IndexRecordMultilingualSystemFieldMappingDataModel.translationProcess":"The process provides the translations for the value of a field in the specified language.\n\nThe process is called once for each defined language with the corresponding locale.\nIt should only provide the translation for this language as the return value.\n\nThe locale of the target language (`$local.locale`) and the original value (`$local.value`) are passed to the process.\n\n**IMPORTANT:** It is advised to reduce ressource heavy executions (e.g. `entities.get*`) to a minimum as it can have major negative performance impact as\nindexing processes will be called repeatedly!\n\n```js\nvar locale = vars.get(\"$local.locale\");\nvar keyword = vars.get(\"$local.value\");\n\nresult.string(translate.text(keyword, locale));\n```","IndexRecordMultilingualSystemFieldMappingDataModel.mappingProcess":"Process, which provides a mapping for all possible values (keywords) to their respective translations.\n\nThis process is called once for each language before indexing.\n\nAs result a json object containing the complete mapping for the requested language is expected.\n\nThe requested locale of the target language is passed via (`$local.locale`) to the process.\n\n```js\n// the requested language locale\nvar locale = vars.getString(\"$local.locale\")\n\n// Value of in DB (keyword) -> translation\nvar mapping = {};\nmapping[\"f\"] = translate.text(\"Female\", locale);\nmapping[\"m\"] = translate.text(\"Male\", locale);\n\n// possible result for locale 'de'.\nvar mapping = {\n\t\"f\":\"Weiblich\"\n\t\"m\":\"Männlich\"\n};\n```","IndexRecordFieldMappingDataModel.keepOriginalInput":"Defines whether the original input of the field is stored in a separate copy field without special analysis.\nIn this case all special characters are preserved and can be searched for additionally.\nDefault is `false`.\n\nThis allows, for example, to search for a value such as a proper name with special characters,\neven if the actual field type removes them during indexing.\nExample: `my@company®`\nThe value can then be found for inputs such as `my@*` or `*any®*` and provide better results for exact matches.","IndexRecordSystemFieldMappingDataModel.templateProcess":"Defines a process which delivers a template for the index field.\n\nThe process allows to create a composed field using the values of other RecordFields in the document.\n\nThe template is generated once before indexing. If the field is multilingual, a template is created for each language of the index.\nDuring indexing, the placeholders in the template are filled with the contents of the fields at the specified position of the indexFieldMappings.\n\n**NOTE:** The indices of the placeholders start at `0`, so the actual position is the number viewed in the `recordFieldMappings` editor **minus** 1, e.g. `#TITLE = 2 (editor) - 1 -> actual index 1.`\n\nIf the field of the template is multilingual, the entries in the corresponding language are adopted from other multilingual fields.\nOtherwise, the template will only use the value of the default language.\n\nThis option can only be used by single valued fields (`isMultiValued == false`).\nIf this field is defined as multilingual (`isMultiLangauge == true`) all other translation settings are ignored.\n\nThe locale of the language can be retrieved via `vars.get(\"$local.locale\")`.\n\n```js\nvar locale = vars.get(\"$local.locale\");\nresult.string(\"{0} {1} | \" + translate(\"Phone\", locale) + \": {2} | \" \n\t+ translate(\"Email\", local) + \": {3}\");\n// result (en): \"{0} {1} | Phone: {2} | Email: {3}\"\n// -> Example: \"Lisa Sommer | Phone:123 | Email: l.sommer@domain.local\"\n```","IndexRecordFieldMappingDataModel.boostValue":"Multiplies the score for all hits in this field with specified value.\n\nThe default is 1.0, for no boost.\n\nOnly positive values greater than 0 are allowed.\n\nIf a value greater than 1 is specified, hits in this field result in a higher score.\nIf a value smaller than 1 is specified, e.g. 0.5, they get a lower score.","IndexRecordFieldMappingDataModel.boostFunction":"Defines the Boost Functions that is used to influence the score based on the actual field value within a document.\n\nThe boost will only be applied is a function is specified.\nDefault is NULL for no function.\n\n**IMPORTANT:** Most functions only work with specific field types!\n\n* `DEFAULT`: Represents a root function. Defined by the given exponent. `pow(pow(sum(1,field-value),exponent),weight)` This function only supports numerical fields (`INTEGER`, `DOUBLE`, `LONG`).\n* `DATE`: Represents a reciprocal function that scores more recent dates higher. This function only supports fields of the type `DATE`.","IndexRecordFieldMappingDataModel.boostWeight":"Gives the used Boost Function a higher/lower importance in score calculation. Default value is 1.0.","IndexRecordFieldMappingDataModel.boostExponent":"Exponent for the DEFAULT function. Default value is 0.1 (Boost Value of 2.0 is reached at a field value of 1024). Should always be between 0 and 1.\n\n* **High: Graph gets steeper. Boost value of 2.0 is reached faster.**\n* **Low: Graph gets flatter. Boost value of 2.0 is reached slower.**","NeonViewReferenceDataModel.colspan":"The colspan of the element","NeonViewReferenceDataModel.entityField":"The field on which the referenced view is working. #ENTITY is your own entity","NeonViewReferenceDataModel.rowspan":"The rowspan of the element","NeonViewReferenceDataModel.view":"View that is referenced and displayed","NeonViewReferenceDataModel.includeInBuild":"Whether this model should be included in the build process.","KeyModifierDataModel.keyModifier":"key modifier","ShortcutDataModel.key":"The main key","ShortcutDataModel.keyModifiers":"multiple key modifiers","INeonComponentContainerFieldDataModel.children":"List of children in this container","IViewTemplateDataModel.title":"Title of the component","IGridLayoutPositionProviderDataModel.colspan":"The colspan of the element","ActionListViewTemplateDataModel.titleField":"Field which stores the title of the view template","IGridLayoutPositionProviderDataModel.rowspan":"The rowspan of the element","ActionListViewTemplateDataModel.descriptionField":"Field which stores the description of the view template","ActionListViewTemplateDataModel.iconField":"Field which stores the icon of the view template","ActionListViewTemplateDataModel.entryAction":"Entry action of the view template. This action is called, if something was entered into the component","ActionsViewTemplateDataModel.fields":"Container for datamodel fields, e.g. for tables","ActionsViewTemplateDataModel.actions":"List of actions and action groups that should be shown in the template.\nActions are shown as individual buttons whereas action groups are shown as popup components that contain all of the actions of the group.","AppointmentEditViewTemplateDataModel.uidField":"Field which stores the uid of the appointment","AppointmentEditViewTemplateDataModel.summaryField":"Field which stores the summary of the appointment","AppointmentEditViewTemplateDataModel.descriptionField":"Field which stores the description of the appointment","AppointmentEditViewTemplateDataModel.beginField":"Field which stores the begin date of the appointment","AppointmentEditViewTemplateDataModel.endField":"Field which stores the end date of the appointment","AppointmentEditViewTemplateDataModel.attendeesField":"Field which stores the attendees of the appointment","AppointmentEditViewTemplateDataModel.privateField":"Field which stores the private flag of the appointment","AppointmentEditViewTemplateDataModel.statusField":"Field which stores the status of the appointment","AppointmentEditViewTemplateDataModel.locationField":"Field which stores the location of the appointment","AppointmentEditViewTemplateDataModel.linksField":"Field which holds the list of links","AppointmentEditViewTemplateDataModel.categoriesField":"Field which stores the categories of the appointment","AppointmentEditViewTemplateDataModel.alldayField":"Field which stores the all day flag of the appointment","AppointmentEditViewTemplateDataModel.transparencyField":"Field which stores the transparency flag of the appointment","AppointmentEditViewTemplateDataModel.organizerField":"Field which stores the organizer of the appointment","AppointmentEditViewTemplateDataModel.ownerField":"Field which stores the owner of the appointment","AppointmentEditViewTemplateDataModel.rruleField":"Field which stores the recurrence rule of the appointment","AppointmentEditViewTemplateDataModel.recurrenceIdField":"Field which stores the recurrence flag of the appointment","AppointmentEditViewTemplateDataModel.saveScopeField":"Field which determines, if a single element of series or the whole series is edited","AppointmentEditViewTemplateDataModel.masterBeginField":"Contains the start date of the master element of a series","AppointmentEditViewTemplateDataModel.masterEndField":"Contains the end date of the master element of a series","AppointmentEditViewTemplateDataModel.reminderField":"Field, which stores the reminder of the appointment","AppointmentEditViewTemplateDataModel.appointmentLinkField":"No description available","AppointmentEditViewTemplateDataModel.appointmentLinkTypeField":"No description available","AppointmentEditViewTemplateDataModel.favoriteActionGroup1":"Actiongroup containing additional actions for appointments","AppointmentPreviewViewTemplateDataModel.uidField":"Field which stores the uid of the appointment","AppointmentPreviewViewTemplateDataModel.summaryField":"Field which stores the summary of the appointment","AppointmentPreviewViewTemplateDataModel.descriptionField":"Field which stores the description of the appointment","AppointmentPreviewViewTemplateDataModel.beginField":"Field which stores the begin date of the appointment","AppointmentPreviewViewTemplateDataModel.endField":"Field which stores the end date of the appointment","AppointmentPreviewViewTemplateDataModel.periodField":"No description available","AppointmentPreviewViewTemplateDataModel.attendeesField":"Field which stores the attendees of the appointment","AppointmentPreviewViewTemplateDataModel.privateField":"Field which stores the private flag of the appointment","AppointmentPreviewViewTemplateDataModel.alldayField":"Field which stores the all day flag of the appointment","AppointmentPreviewViewTemplateDataModel.transparencyField":"Field which stores the transparency flag of the appointment","AppointmentPreviewViewTemplateDataModel.statusField":"Field which stores the status of the appointment","AppointmentPreviewViewTemplateDataModel.locationField":"Field which stores the location of the appointment","AppointmentPreviewViewTemplateDataModel.linkField":"Field which holds the list of links","AppointmentPreviewViewTemplateDataModel.organizerField":"Field which stores the organizer of the appointment","AppointmentPreviewViewTemplateDataModel.ownerField":"Field which stores the owner of the appointment","AppointmentPreviewViewTemplateDataModel.categoriesField":"Field which stores the categories of the appointment","AppointmentPreviewViewTemplateDataModel.recurrenceIdField":"Field which stores the recurrence flag of the appointment","AppointmentPreviewViewTemplateDataModel.favoriteActionGroup1":"Actiongroup containing additional actions for appointments","AppointmentPreviewViewTemplateDataModel.favoriteActionGroup2":"Actiongroup containing additional actions for appointments","INeonSystemActionCreatableDataModel.isCreatable":"Creatable yes/no.","INeonColumnDataModel.columns":"Contains all defined columns for this component.","INeonSystemActionEditableDataModel.isEditable":"Editable yes/no.","INeonSystemActionDeletableDataModel.isDeletable":"Deletable yes/no.","BasicTableViewTemplateDataModel.hideActions":"Determines if actions are shown or not.","BasicTableViewTemplateDataModel.hideContentSearch":"If true, the content search is disabled in the table.","INeonFavoriteActionGroupsDataModel.favoriteActionGroup1":"First action group to place additional actions in","INeonFavoriteActionGroupsDataModel.favoriteActionGroup2":"Second action group to place additional actions in","INeonFavoriteActionGroupsDataModel.favoriteActionGroup3":"Third action group to place additional actions in","IViewRendererMappingDataModel.viewRendererMapping":"Mapping that specifies how an entity field should be rendered in view mode.\nIf no custom mapping is defined the default renderers are used.","IEditRendererMappingDataModel.editRendererMapping":"Mapping that specifies how an entity field should be rendered in edit mode.\nIf no custom mapping is defined the default renderers are used.","INeonTableDataModel.isSaveable":"Saveable yes/no.","INeonColumnAutoNewRowDataModel.autoNewRow":"Determines if a new row should be added automatically, if the record state is NEW","INeonTableDataModel.linkedFrame":"Linked frame that is executed on action.","INeonRowBasedDataModel.maxDBRow":"Sets the maximum number of data rows to be gathered from the database","IViewTemplateInformationDataModel.informationField":"Defines the field which provides additional information. The placement of the information label varies between the ViewTemplates. The information label is only shown once per ViewTemplate.","CardTableViewTemplateDataModel.entryAction":"Determines the action for an entry","CardTableViewTemplateDataModel.hideActions":"Determines, if actions are shown or not","CardTableViewTemplateDataModel.iconField":"Determines the field, that holds the icon","CardTableViewTemplateDataModel.hideContentSearch":"If true, the content search of the table is hidden.","CardTableViewTemplateDataModel.titleField":"Entity field, which holds the title","CardTableViewTemplateDataModel.subtitleField":"Entity field, that hold an additional title. Shown below the title field","CardTableViewTemplateDataModel.descriptionField":"Entity field, that holds the description text","CardViewTemplateDataModel.iconField":"Field, which determines the icon","CardViewTemplateDataModel.titleField":"Field, which holds the title","CardViewTemplateDataModel.subtitleField":"Field, which hold an additional title. Shown below the title.","CardViewTemplateDataModel.descriptionField":"Field, which holds the description text","CardViewTemplateDataModel.objectType":"Field which stores the objectType of the favorite","CardViewTemplateDataModel.rowId":"Field which stores the rowId of the favorite","CardViewTemplateDataModel.favoriteAction1":"First actiongroup for additional actions","CardViewTemplateDataModel.favoriteAction2":"Second actiongroup for additional actions","DragAndDropViewTemplateDataModel.dropAction":"Action that gets executed on drop","DragAndDropViewTemplateDataModel.descriptionField":"Field containing the description","DynamicFormViewTemplateDataModel.formDefinition":"Field which content should provide the definition of the form (in JSON format).","DynamicFormViewTemplateDataModel.formResult":"Field in which the result of the form should be written to (in JSON format).","DynamicFormViewTemplateDataModel.editMode":"Switches between read only mode or edit mode of the template.","DynamicMultiDataChartViewTemplateDataModel.chartType":"Defines the type of the chart.\n\nNote: If you use an aggregate entity field, you have to set the aggregated field next to the entity field in the columns.","INeonPropertyChartPlotOptionsDataModel.showDataLabelValues":"Specifies if the data labels of the chart should show the actual numeric values.","INeonPropertyChartPlotOptionsDataModel.dataLabelPositionInside":"Specifies if the data labels should be shown inside the data points.\nCurrently not supported in pie / donut charts.","DynamicMultiDataChartViewTemplateDataModel.yAxisLabel":"Defines the label for the Y Axis. As the Y Axis can present multiple axes at the same time, we can not determine the label dynamically, therefore we have to defined it statically.","DynamicMultiDataChartViewTemplateDataModel.shareParent":"Defines if the current parent shall be shared with other hierarchy based ViewTemplates.\nA new parent will be set if you drill down on a series.","DynamicMultiDataChartViewTemplateDataModel.stacked":"Specifies if multiple y-axes should be stacked on top of eachother instead of being displayed adjacent to eachother.\nDifferent chart types will display the stacked property differently.","INeonPropertyDefaultGroupFields.defaultGroupFields":"Has to contain a list of fields which are used for grouping the data.\nThese grouping fields are set when the view is loaded and no fields have been set by the user.\nIf a default filter with grouping has been defined, they will overwrite the default grouping.","DynamicSingleDataChartViewTemplateDataModel.chartType":"Defines the type of the chart.\n\nNote: If you use an aggregate entity field, you have to set the aggregated field next to the entity field in the columns.","DynamicSingleDataChartViewTemplateDataModel.shareParent":"Defines if the current parent shall be shared with other hierarchy based ViewTemplates.\nA new parent will be set if you drill down on a series.","FavoriteViewTemplateDataModel.objectType":"Field which stores the objectType of the favorite","FavoriteViewTemplateDataModel.rowId":"Field which stores the rowId of the favorite","GanttViewTemplateDataModel.groupByRootElements":"If this box is checked, the arrows from the first level (root element) to the second level is not displayed.","GanttViewTemplateDataModel.hideArrows":"If this box is checked, all the arrows in the gantt chart will not displayed.","GanttViewTemplateDataModel.uidField":"Defines the entityfield in which the UID is located.\n\nThis serves as the parent/child mapping for the rows of a TreeTable.","GanttViewTemplateDataModel.titleField":"Defines the Title, which is displayed in the Step.","GanttViewTemplateDataModel.descriptionField":"Defines the description, which is displayed in the tooltip of a step.","GanttViewTemplateDataModel.beginDateField":"Defines the beginDate of a Step.\nThis is required to correct the length of the step and when the step starts.","GanttViewTemplateDataModel.endDateField":"Defines the endDate of a Step.\nThis is required to correct the length of the step and when the step is over.","GanttViewTemplateDataModel.predecessorIdField":"Defines the entityfield in which the PredecessorId is located.\n\nThis serves as the parent/child mapping for the rows of a TreeTable.","GanttViewTemplateDataModel.isSubstep":"This Bool defines, if the row is a standalone Step or a Sub Step of the parent Step.\nIf the transferred value is true, this line is integrated as a sub-step in the higher-level step.","GanttViewTemplateDataModel.stepColorField":"Depending on this property, the steps can be shown in another color than their successors","GanttViewTemplateDataModel.stepProgress":"Defines the entityfield in which the stepProgress is located.\n\nThis is displayed in a level and transferred as a percentage. The range of values is from 0 to 100","GanttViewTemplateDataModel.initialStartDateField":"Defines the entityfield in which the initialStartDate is located.\n\nThis is used to set the time limit for the timeline in the Gantt. If there are steps that come before the initialStartDate, they are shown in the TreeTable, but not in the Gantt.","GanttViewTemplateDataModel.initialEndDateField":"Defines the entityfield in which the initialEndDateField is located.\n\nThis is used to set the time limit for the timeline in the Gantt.\nIf there are steps that come after the initialStartDate, they are shown in the TreeTable, but not in the Gantt.","INeonFieldGroupDataModel.fields":"Container for datamodel fields, e.g. for tables","GenericViewTemplateDataModel.editMode":"Switches between read only mode or edit mode of the generic","GenericViewTemplateDataModel.showDrawer":"Determines, if the drawer is shown above the generic","GenericViewTemplateDataModel.drawerCaption":"The caption of the drawer.","GenericViewTemplateDataModel.fixedDrawer":"Determines, if the drawer is always open or if it can be minimized","GenericViewTemplateDataModel.hideLabels":"Determines, if the field labels are shown or hidden","GenericViewTemplateDataModel.hideEmptyFields":"Determines, if fields that have no content are hidden or always shown","ITextPositionDataModel.isLabelPositionTop":"Defines if the label position of a FormItem is on top or to the side","ITextPositionDataModel.textAlignment":"Specifies the text alignment for all of the values of the viewtemplate (default = left).","IndexSearchViewTemplateDataModel.indexGroups":"Determine which index groups should be available for the search via the viewtemplate","LookupViewTemplateDataModel.consumerField":"Field which consumer should be used as the source for the lookup component.\n\n<!--EOF-->\n\nThe UID of the selected dataset will then be assigned as value of the Entity field specified in property `consumerField`. This Entity field must have a Consumer that is connected with a Provider of the other Entity that holds the datasets from which the user wants to select.","LookupViewTemplateDataModel.consumerPresentationMode":"The presentation mode that should be used for the lookup component.\n* `POPUP` -> The lookup view of the consumer will be shown within a popup adjacent to the field.\n* `EMBEDDED` -> The lookup view of the consumer will be shown inside its parent view.","MapViewTemplateDataModel.autoGeneratedMarkerLatitudeField":"Field for the latitude of a marker that is generated based on the data","MapViewTemplateDataModel.autoGeneratedMarkerLongitudeField":"Field for the longitude of a marker that is generated based on the data","MapViewTemplateDataModel.autoGeneratedMarkerIconField":"EntityField providing image information, in order to replace the standard marker icon by a specific icon to be used for the generated marker of the individual dataset.\n\nSimply choose from the icon names provided in the combobox of every property named `icon`, and make sure you are using the exact spelling, e.g., `VAADIN:FACTORY`.\n\nAlternatively, you may provide image data in base64 String format (but note that, in this case, property `autoGeneratedMarkerColorField` has no effect).","MapViewTemplateDataModel.autoGeneratedMarkerColorField":"Field to give the generated marker a color. The field must provide the color code as color constant, e.g. `neon.PRIORITY_HIGH_COLOR`. You can also directly provide the corresponding String, e.g., `priority-high-color` (but then make sure you are using exactly the spelling shown in the list of color codes provided by the combobox of every property named `color`).","MapViewTemplateDataModel.autoGeneratedMarkerPopupField":"Field to give the generated marker a popup (similar to a tooltip; not available on all devices) as HTML (!) String including additional information referring to the location.","MapViewTemplateDataModel.configField":"Field to specify a configuration for the map. This provides the ViewTemplate with the information what map data needs to be loaded.\n\nContent needs to be JSON with the following properties:\n* `startingCenterPosition`; type: Object with these properties:\n\t* `lat`; type: decimal, latitude position of the starting center position\n\t* `lon`; type: decimal, longitude position of the starting center position\n\t* `zoomLevel`; type: integer, initial zoom level\n\t* `autoLocate`; type: boolean, if true tries to set the center the current location of the device\n* `boundaries`; type: Object with these properties:\n\t* `minZoom`; type: integer, the minimal zoom that can be used\n\t* `maxZoom`; type: integer, the maximal zoom that can be used\n* `tiles`; a definition of possible map tiles (= map sources) from which the user can choose; type: Array of Objects, with each object having the following properties:\n\t* `title`; type: String Display title for the User, e.g. \"ADITO Road\"\n\t* `url`; type: String URL to the server that provides the tiles in the \"xyz\" format, with the following placeholders:\n\t\t* `{s}` means one of the available subdomain\n\t\t* `{z}` the zoom level\n\t\t* `{x}` and `{y}` the tile coordinates\n\t\t* `{r}` can be used to add `@2x` to the URL to load retina tiles\n\t* `attribution`; type: String, HTML content for display the attribution information (e.g., copyright and sources)\n\nThe content of the field is only loaded once.","MapViewTemplateDataModel.geoJsonFeatureCollectionField":"Field to provide an array of GeoJSON-FeatureCollections to create additional elements.\n\nThe following GeoJSON types are supported right now:\n* `Point`\n* `Polygon`\n* `MultiPolygon`\n* `LineString`\n* `LinearRing`\n\nThe following custom properties are available:\n* `ADITO-color`, color constant value for the color of the element\n* `ADITO-targetId`, targetContext (contextname) and targetId (uid) can be used to provide information for a preview view onclick\n* `ADITO-targetContext` targetContext (contextname) and targetId (uid) can be used to provide information for a preview view onclick\n* `ADITO-icon`, icon constant for an icon (only Point)\n* `ADITO-label`, title text to display (only Point)\n* `ADITO-radius`, Integer number that specifies meters to draw a circle (only Point)","INeonPropertyHideHeaderDataModel.hideHeader":"Defines if the column headers of the grid shall be hidden.","MultiDataChartViewTemplateDataModel.chartType":"Specifies the display of the chart:\n\n* `AREA`\n* `BAR`\n* `COLUMN`\n* `SPLINE`\n* `LINE`\n\n<!--VSCODE_ONLY-->","MultiDataChartViewTemplateDataModel.stacked":"Specifies if multiple y-axes should be stacked on top of eachother instead of being displayed adjacent to eachother. Different chart types will display the stacked property differently.","MultiDataChartViewTemplateDataModel.xAxis":"Specifies the entityfield in which the x-axis values are.","MultiDataChartViewTemplateDataModel.yAxis":"Defines the entityfield in which the values of the y-axis are","MultiDataChartViewTemplateDataModel.parentField":"Defines the entity field in which the ParentID is located.\n\nThis serves as the parent/child mapping for chart drilldown or mapping for the rows of a TreeTable.","MultiDataChartViewTemplateDataModel.categoryField":"Field, which stores the category information","MultiDataChartViewTemplateDataModel.colorField":"Defines the entityfield in which the color of each value in the chart is located. \ne.g. if the value provided in this field is `brand-color` then the item in the chart will be rendered in this color.","ILayoutMappingDataModel.layoutMapping":"Maps a column to specific layout properties e.g. textAlignment","INeonLinkedColumnDataModel.linkedColumns":"Defines the columns which shall be displayed as a native link.","INeonPropertyFixedFilterFieldsDataModel.fixedFilterFields":"Defines the fields which shall be always shown on the filter. The will not be able to remove them entirely.","MultiEditTableViewTemplateDataModel.editableColumns":"Defines the columns which shall be editable all the time. This will basically display the selected columns as editable components.","MultiEditTableViewTemplateDataModel.hideColumnSelector":"If true, the column selector of the table is hidden.","MultiEditTableViewTemplateDataModel.dynamicTable":"Determines if the table processes new rows and deleted rows by itself and dynamically shows or hides the rows. The changes are only in the cache and are only stored when saving.\nIf no dynamic table is active, new rows are created for example via SmallEdit and are stored directly. The MultiEditTable is then reloaded. Rows are also deleted immediately and the MultiEditTable is then reloaded.","MultiEditTableViewTemplateDataModel.focusNewLineOnInsert":"Determines, if the new added row should be focused.\n\n<!--EOF-->\n\nThis property is only used when `dynamicTable` is set to `true`.","PictureViewTemplateDataModel.pictureField":"Field which content should provide the image data for the template (as Base64 string).","PictureViewTemplateDataModel.pictureClickAction":"Action that should be executed when the picture is clicked.","ReportViewTemplateDataModel.reportData":"Defines the field which provides the data of the report. The data has to be provided as a base64 encoded byte-array.\nThe report can be exported as a base64 encoded byte-array using `report.exportToBytes(...)`.","ResourceTimelineViewEntriesDataModel.entityField":"Entityfield to load the entries for the Resources.\nThis is a consumer within the entity specified in the Resource-entityField.\nOther properties are dependent on this value.","ResourceTimelineViewEntriesDataModel.titleField":"Entityfield, that holds the title information. This is used to display the planning entry.","ResourceTimelineViewEntriesDataModel.resourceIdField":"Entityfield that contains the resource-reference as ID value of the resource.\nThis field is mandatory to assign the entry to the resource whose ID is referenced in this field. The field needs also to be filterable, otherwise an error is thrown during runtime.","ResourceTimelineViewEntriesDataModel.datetimeStartField":"Entityfield that contains the start date and time of an entry.\nThis property is mandatory and the field needs to be filterable and of contentType `DATE` - otherwise an error is thrown during runtime.","ResourceTimelineViewEntriesDataModel.datetimeEndField":"Entityfield that contains the end date and time of an entry.\nThis property is mandatory and the field needs to be filterable and of contentType `DATE` - otherwise an error is thrown during runtime.","ResourceTimelineViewEntriesDataModel.colorField":"Entityfield, that holds the constant for the color information. This is used as default value for the entries of this resource.\nWhen no field is set or the field-value is empty the brand color is used as default.","ResourceTimelineViewEntriesDataModel.selectedResourcesField":"Entityfield, that holds the IDs of the selected resources of the timeline. The IDs are provided in a JSON array.","ResourceTimelineViewEntriesDataModel.resourceOperationIdField":"Entityfield that contains the resource-operation-reference as ID value.\nThis field is mandatory to find the same resource operation from other resources.","ResourceTimelineViewTemplateDataModel.titleField":"Entityfield, that holds the title information. This is used to display the resource.","ResourceTimelineViewTemplateDataModel.colorField":"Entityfield, that holds the constant for the color information. This is used as default value for the entries of this resource.\nWhen no field is set or the field-value is empty the brand color is used as default.","ResourceTimelineViewTemplateDataModel.initialDateField":"Entityfield, that holds the date which should be initially shown in the timeline.\nIf no field is set or the field returns a null value then the current day is used.\nThe format of the date should be in ISO-8601 format `uuuu-MM-dd`. e.g. 2022-08-30","ResourceTimelineViewTemplateDataModel.parentField":"Entity-field which contains the ParentID.\n\nThis serves as the parent/child mapping for the resources of the timeline component.\nA value of null within the entityfield is interpreted root.","ResourceTimelineViewTemplateDataModel.businessHoursField":"Entityfield, that holds the configuration for the business hours.\nBy specifying it, the business hours will be emphasized. Possible values are:\n\n* null/empty => no emphasis\n* JSON array of businessHours\n\t\n\t```json\n\t\t[\n\t\t\t{\n\t\t\t\tdaysOfWeek: [ 1, 2, 3 ], // Monday, Tuesday, Wednesday\n\t\t\t\tstartTime: '08:00', // 8am\n\t\t\t\tendTime: '18:00' // 6pm\n\t\t\t},\n\t\t\t{\n\t\t\t\tdaysOfWeek: [ 4, 5 ], // Thursday, Friday\n\t\t\t\tstartTime: '10:00', // 10am\n\t\t\t\tendTime: '16:00' // 4pm\n\t\t\t}\n\t\t]\n\t```","ResourceTimelineViewTemplateDataModel.useUserTimeSlot":"Determines whether the user is allowed to set his own displayed time slot.","ResourceTimelineViewTemplateDataModel.slotMinTime":"First time slot that will be displayed for each day.","ResourceTimelineViewTemplateDataModel.slotMinTimeProcess":"Process that overrides the static `slotMinTime` and calculates the value by using JDito.","ResourceTimelineViewTemplateDataModel.slotMaxTime":"Last time slot that will be displayed for each day.","ResourceTimelineViewTemplateDataModel.slotMaxTimeProcess":"Process that overrides the static `slotMaxTime` and calculates the value by using JDito.","ResourceTimelineViewTemplateDataModel.hideContentSearch":"If set to true, the content search is hidden.","ScoreCardViewTemplateDataModel.fields":"Container for datamodel fields, e.g. for tables","ScoreCardViewTemplateDataModel.fieldActions":"Actions that correspond to the linked fields of the template.\nThe first action is mapped to the first field and will be executed when the component of the first field is clicked.","SignatureViewTemplateDataModel.imageField":"Entity field, which holds the image data of the signature as a base64 string","SingleDataChartViewTemplateDataModel.chartType":"Specifies the display of the chart:\n\n* `DONUT`\n* `FUNNEL`\n* `PIE`\n* `PYRAMID`\n\n<!--VSCODE_ONLY-->","SingleDataChartViewTemplateDataModel.xAxis":"Specifies the entityfield in which the x-axis values are.","SingleDataChartViewTemplateDataModel.yAxis":"Defines the entityfield in which the values of the y-axis are.","SingleDataChartViewTemplateDataModel.parentField":"Defines the entityfield in which the ParentID is located.\n\nThis serves as the parent/child mapping for chart drilldown or mapping for the rows of a TreeTable.","SingleDataChartViewTemplateDataModel.colorField":"Defines the entityfield in which the color of each value in the chart is located.\ne.g. if the value provided in this field is \"brand-color\" then the item in the chart will be rendered in this color.","StepperViewTemplateDataModel.stateField":"Defines the field which provides the state of the current step. Possible values: `INVISIBLE`, `DISABLED`, `ACTIVE`, `EDITABLE`.","StepperViewTemplateDataModel.titleField":"Defines the field which provides the title for the current step.","StepperViewTemplateDataModel.iconField":"Defines the field which provides the icon for the current step.","TableViewTemplateDataModel.iconField":"Determines the field, that holds the icon that is used if the table is transformed to a CardTable (e.g. on mobile devices)","INeonInitialVisibleColumnsDataModel.initialVisibleColumns":"Determines, which columns the table should display initially. If none are set then all columns will be visible.\nOther configured columns from the \"columns\"-property will still be available for the user within the columnSelector component.","TableViewTemplateDataModel.titleField":"Entity field, which holds the title that is used if the table is transformed to a CardTable (e.g. on mobile devices)","TableViewTemplateDataModel.subtitleField":"Entity field, that holds an additional title that is used if the table is transformed to a CardTable (e.g. on mobile devices). Shown below the title field","TableViewTemplateDataModel.descriptionField":"Entity field, that holds the description text that is used if the table is transformed to a CardTable (e.g. on mobile devices)","TableViewTemplateDataModel.entryAction":"Determines the action for an entry","TableViewTemplateDataModel.hideActions":"Determines, if actions are shown or not","TableViewTemplateDataModel.hideContentSearch":"If true, the content search of the table is hidden.","TableViewTemplateDataModel.inlineEdit":"Determines, if the user is able to edit data with the table itself","TableViewTemplateDataModel.hideColumnSelector":"If true, the column selector of the table is hidden.","TilesViewTemplateDataModel.iconField":"Field, which determines the icon. It will be displayed on the left.","TilesViewTemplateDataModel.titleField":"Field, which holds the title. It will be displayed on the right","TilesViewTemplateDataModel.subtitleField":"Field, which hold an additional title. Shown below the title.","TilesViewTemplateDataModel.descriptionField":"Field, which holds the description text","TilesViewTemplateDataModel.infoTopField":"Field, which holds the text for the information in the top right corner of the tile","TilesViewTemplateDataModel.infoBottomField":"Field, which holds the text for the information in the bottom right corner of the tile","TilesViewTemplateDataModel.hideActions":"Determines, if actions are shown or not","TilesViewTemplateDataModel.hideContentSearch":"If true, the content search of the view is hidden.","TilesViewTemplateDataModel.tilePresentation":"Determines how the tiles are shown inside the client.\n\n* `LANDSCAPE`: icon on the left side of the tile, text on the right. There will be 3 tiles in a row with dynamic width.\n* `PORTRAIT`: icon on top of the tile, text below the icon. There will be a dynamic number of tiles per row with a fixed width.\n\n<!--VSCODE_ONLY-->","TilesViewTemplateDataModel.direction":"Determines in wich direction the layout should be scrolled (vertical or horizontal).\nMobile devices always use vertical and ignores this option.","TimelineViewTemplateDataModel.dateField":"Field, which has told hold the date used to create the timeline","TimelineViewTemplateDataModel.titleField":"This field has to hold the title information","TimelineViewTemplateDataModel.descriptionField":"Field, which holds the description value","TimelineViewTemplateDataModel.subdescriptionField":"Field, that hold an additional desrciption value","TimelineViewTemplateDataModel.iconIdField":"Field, that has to hold the icon id.\nExample: `\"TEXT:\"+value` or `NEON:ADITO` or similar icon ids.","TimelineViewTemplateDataModel.additionalInfoField":"A field, that can hold additional information","TimelineViewTemplateDataModel.entryAction":"Action, that is performed on double click on the entry","TimelineViewTemplateDataModel.hideActions":"Determines, if the action buttons are hidden or not","TimelineViewTemplateDataModel.hideContentSearch":"If set to true, the content search is hidden.","TimelineViewTemplateDataModel.hideTime":"Hides the time part of the date.\n\nExample: `28.01.2020 11:30` is shown as `28.01.2020` if this property is set to `true`.","TimelineViewTemplateDataModel.orderByDate":"Determines, if the timeline automatically sorts by the date field","TitledListViewTemplateDataModel.titleField":"Field, that hold the title information","TitledListViewTemplateDataModel.highlightingField":"Has to contain the information, that should be highlighted","TitledListViewTemplateDataModel.titleFieldFullWidth":"Determines, if the title field can utilize the full width or is restricted","TitledListViewTemplateDataModel.fixedDrawer":"Determines, if the drawer can be minimized or not","TitledListViewTemplateDataModel.rowLimit":"Limit the amount of rows displayed and then show a show more button","TreeTableViewTemplateDataModel.parentField":"Defines the entityfield in which the ParentID is located.\n\nThis serves as the parent/child mapping for chart drilldown or mapping for the rows of a TreeTable.","TreeTableViewTemplateDataModel.enableDragAndDrop":"Defines if drag and drop functionality within the TreeTable is enabled or not.\nIf enabled it's possible for the user to drag rows onto new parent rows.\n\n<!--EOF-->\n\nThis property is only used if `parentField` is set.","TreeTableViewTemplateDataModel.iconField":"Determines the field, that holds the icon that is used if the table is transformed to a CardTable (e.g. on mobile devices)","TreeTableViewTemplateDataModel.titleField":"Entity field, which holds the title that is used if the table is transformed to a CardTable (e.g. on mobile devices)","TreeTableViewTemplateDataModel.subtitleField":"Entity field, that holds an additional title that is used if the table is transformed to a CardTable (e.g. on mobile devices). Shown below the title field","TreeTableViewTemplateDataModel.descriptionField":"Entity field, that holds the description text that is used if the table is transformed to a CardTable (e.g. on mobile devices)","TreeTableViewTemplateDataModel.nodeExpandedField":"Defines the field which defines if the node shall be initially expanded or not.\n\nWhen enabling this property then performance issues might arise when too many nodes are automatically expanded.\n\nOnly works for trees with a mapped parentField.","TreeTableViewTemplateDataModel.hideActions":"Determines if the action buttons are hidden or not","TreeTableViewTemplateDataModel.entryAction":"A action that is executed on double click on an entry","TreeTableViewTemplateDataModel.hideContentSearch":"Determines, if the content search of the treetable is hidden or not.","TreeTableViewTemplateDataModel.hideColumnSelector":"If true, the column selector of the table is hidden.","TreeTableViewTemplateDataModel.showChildrenCount":"Determines, if the count of the underlying children is shown","TreeTableViewTemplateDataModel.expandRootItems":"Defines if the items in the root level should be expanded initially.\n\nWhen enabling this property performance issues might arise when too many root nodes are automatically expanded.","TreeTableViewTemplateDataModel.useBreadCrumbs":"Determines if the current `TREE_TABLE` or `TREE` should use the bread-crumb variant for Tablet.\nIt will always be used on Mobile and never on Desktop\n\n\n* `true` - the bread-crumb variant will be used for Tablet and Mobile\n* `false` - the bread-crumb variant will only be used on Mobile\n* **default:** `false`","TreeViewTemplateDataModel.parentField":"Defines the entity field in which the ParentID is located.\n\nThis serves as the parent/child mapping for chart drilldown or mapping for the rows of a TreeTable.","TreeViewTemplateDataModel.nodeTypeField":"Defines the field which provides the type of the node. Possible values: `NODE`, `DEFAULT`.","TreeViewTemplateDataModel.nodeExpandedField":"Defines the field which defines if the node shall be initially expanded or not.\n\nWhen enabling this property then performance issues might arise when too many nodes are automatically expanded.\n\nOnly works for trees with a mapped parentField.","TreeViewTemplateDataModel.titleField":"Defines the field which provides the title for the current node.","TreeViewTemplateDataModel.descriptionField":"Defines the field which provides the description for the current node.","TreeViewTemplateDataModel.iconField":"Defines the field which provides the icon for the current node.","TreeViewTemplateDataModel.hideActions":"Defines if the actions shall be hidden.","TreeViewTemplateDataModel.entryAction":"Determines the action for an entry","TreeViewTemplateDataModel.hideContentSearch":"If true, the content search of the table is hidden.","TreeViewTemplateDataModel.showChildrenCount":"Defines if children count for a grouped row shall be shown.","TreeViewTemplateDataModel.expandRootItems":"Defines if the items in the root level should be expanded initially.\n\nWhen enabling this property performance issues might arise when too many root nodes are automatically expanded.","TreeViewTemplateDataModel.useBreadCrumbs":"Determines if the current `TREE_TABLE` or `TREE` should use the bread-crumb variant for Tablet.\nIt will always be used on Mobile and never on Desktop\n\n\n* `true` - the bread-crumb variant will be used for Tablet and Mobile\n* `false` - the bread-crumb variant will only be used on Mobile\n* **default:** `false`","WebContentViewTemplateDataModel.width":"The width of the component.","WebContentViewTemplateDataModel.height":"The height of the component.","WebContentViewTemplateDataModel.unit":"The unit of the height/width properties.","LayoutMappingEntryDataModel.fieldName":"Entity field which is displayed using the layout mapping.","LayoutMappingEntryDataModel.textAlignment":"Configuration of the text alignment.","NumberFieldRendererConfigDataModel.numberfieldStep":"Enter a positive number to define the step size for increasing or decreasing the value.","NumberFieldRendererConfigDataModel.numberfieldStepsProcess":"Process in which the steps for increasing or decreasing the value is set.\n\nThe steps are returned in an array. e.g. `result.object([-5, -1, 1, 5]);`","RendererDefinitionDataModel.rendererConfig":"Configuration of the Renderer","RendererMappingEntryDataModel.fieldName":"Entity field which is displayed using the renderer.","RendererMappingEntryDataModel.renderer":"Configuration of the renderer.","ApplicationDataModel.signature":"The signature of the application","ApplicationDataModel.entityNode":"The the root node of the tree structure defining the application","ApplicationDataModel.company":"The information of the company, by which the application is used.","CompanyDataModel.dropAlias":"DB alias used for the global drop process.","CompanyDataModel.title":"Title of your company (speaking name. may contain spaces and special characters.)\n\nThis has no specific effect.","CompanyDataModel.description":"Description","CompanyDataModel.backgroundImage":"Background image that is displayed in the application in the workspace when no tabs are open in the client.","CompanyDataModel.backgroundColor":"Specifies the background color.\n\nAt the application, the background is only colored when no tab has been opened.\n\nThe table fills only the table cells that are below the table headings, the table header itself is not affected by the background color.\n\nThis color code is in the format `0xAARRGGBB`.\n\n* `AA`: The alpha of the color. `FF` means 100% visible (no transparency).\n* `RRGGBB`: The normal hexadecimal RBG code for this color\n\nAll of these values specified above need to be a hexadecimal number. Note that your hex codes need to be wrapped with quotes.\n\n<!--VSCODE_ONLY-->","LanguageDataModel.sqlModels":"Contains SQLs that provide the key assignment for the language.","INeonEntityContainerDataModel.entity":"Specifies the entity to which the context is linked.\n\nFrom the specified entity, the context contains its data and functions.","NeonContextDataModel.viewmodeProvider":"Define a specific provider for the different viewmodes that should be used for loading data","NeonContextDataModel.mainView":"The `MainView` is a detailed view of one specific record (one organisation, one person, etc.)\nIt's used for example if you \"open\" a record in the client.\n\nIn most cases, it should contain the most important data while also providing the possibility to see detail information of that record.\nOften, the `mainView` has a lot of viewReferences to already existing views.","NeonContextDataModel.filterView":"The `filterView` is used for displaying several records (for example in a table-template) that might be filtered. Often the user has the possibility to set filters via the UI.\nNormally the `filterView` is the point where you start as user in the client when you open a context.","NeonContextDataModel.editView":"The `editView` is a view for modifying one entire specific record (one organisation, one person, etc.)\nIt's used for example, when you want to create a new record or edit an existing record. It's not used when you edit only a small part of a record.","NeonContextDataModel.previewView":"The `PreviewView` is a view of one specific record (one organisation, one person, etc.).\nIt's used for example to have a quick overview of a record and should include the most important data.\nSometimes, if there is so less information that it wouldn't make no sense to have a main view, only a preview is used for viewing a record.","NeonContextDataModel.previewMultipleView":"The `PreviewMultipleView` is a summary view of several records of the same type (two selected offers). \nIt's used for example to have a quick summary of several selected records and should include the most important data aggregated.","NeonContextDataModel.lookupView":"The `lookupView` is used whenever the user opens a lookup-component in the client. A lookup-component is loaded for example when you have a recordField within an entity that refers to another entity (via a consumer). The providing entity needs an associated context where the lookupView is loaded when you want to select a record in you consumingEntity. (e.g. select an `organisation` when creating a `contact person`). Saying that, the lookupView is used for displaying several records.\n\n Note that the specified view should've set the `noneLayout`.\n\nIf you do not specify a custom `lookupView`, a default view is used that contains the entities `contentTitle`. This does only work if you've got a `Default_context` that has got a `DefaultLookup_view` which is used in that case.","NeonDashboardDataModel.defaultDashlets":"The preselected dashlets of this dashboard","NeonDashboardDataModel.dashboardType":"The type of the dashboard (either `PUBLIC` or `PRIVATE`)","NeonDashboardDataModel.editRoles":"Determines, which roles may edit this dashboard. Only affects public dashboards.","NeonDashboardDataModel.fixedDashlets":"Determines, if all dashlets on this dashboard are fixed. I.e. not movable, closeable or resizeable by non-authorized users.","NeonNotificationTypeDataModel.archivable":"Set if notification can be moved to the archive to be accessible again later on","NeonNotificationTypeDataModel.deletePerLogout":"If set to yes/true, notifications of this type get deleted on log out.","NeonNotificationTypeDataModel.defaultPriority":"The default priority of this notification type","NeonNotificationTypeDataModel.imageProcess":"Process that reads the image data is returned by `result.string('binary data')`.\n\nFor example, 'binary data' is the value returned by `swing.doClienIntermediate(swing.CLIENTCMD_GETDATA, …)`.\n\nError messages from this process do not arrive at the client, they are only visible in the server log.","NeonNotificationTypeDataModel.onResultOpen":"Action that occurs when you double-click index search results or neon notifications.","NeonNotificationTypeDataModel.onResultOpenIcon":"Icon for the onResultOpen action.","NeonNotificationTypeDataModel.alias":"The database alias that is associated with the notifications.","NeonViewDataModel.dashletConfigurations":"The dashlet configurations of this view","INeonLayoutContainerDataModel.layout":"Type of layout which is used in this container. The layout defines a fundamental way in which the view-plates are arranged.","INeonPropertyQuickEntryDataModel.quickEntry":"Specifies the index at which this model should be in the quick entry list","NeonViewDataModel.filterable":"Determines, if this view is filterable","NeonViewDataModel.size":"Determines the preferred size of the View. If set to `SMALL` the Editmode of the View will be shown in the Preview container.","NeonViewDataModel.isOverlay":"Determines if the View should be shown in an Overlay container instead of being embedded in the Main container.\nSome Layouts may be prohibited to be viewed in Overlays, e.g., MasterDetailLayouts with detail areas are not permitted.","NeonViewDataModel.overlayOrientation":"Determines the preferred orientation of the View when displayed as an Overlay. e.g. if set to `PORTRAIT` then the View will have a Portrait orientation when shown as an Overlay.","ProcessDataModel.alias":"The database alias that is associated with this process and is used by database instructions by default.","ProcessDataModel.webserviceEnabled":"Activates the process as a webservice","ProcessDataModel.publishAsWebservice":"Publishes the process as a webservice","ProcessDataModel.anonymousUsageWebservice":"Allows anonymous access to the webservices when a process is specified as a webservice process.","ProcessDataModel.style":"Type for web services: `REST` or `SOAP`.","ProcessDataModel.iconInactive":"Inactive icon (inverse color to default icon for inactive display in frame tabs.)","IVariant.variants":"List of possible variants.\n\n* Processes that have the property `publishAsWebservice` set, automatically get the variant `webservices`.\n* If you want to start a process in the manager or with the `process` JDito module, you need to assign the variant `executables` to it.\n* Webservices or Workflow-Processes don't need the variant `executables`.\n* Some internally used processes automatically get the variant `internal`, which can't be assigned manually.\n* Processes that are used in imports of other processes have to be assigned the variant `libraries`.","ProcessDataModel.wsdl":"If a process is configured to be provided as a SOAP Webservice, a specific WSDL for SOAP Webservice can be placed here.","ProcessDataModel.restAcceptedMimeType":"MIME types accepted by the rest webservice.","ProcessDataModel.restDeliveredMimeType":"MIME type that the rest webservice returns.","ProcessDataModel.soapOmitEmptyResult":"Specifies whether the return element should be omitted in the SOAP response if no result value is present.","ProcessDataModel.soapUseRawXmlResult":"Specifies whether the result of the process is to be integrated directly as XML in the SOAP response.\nThe result is not encapsulated in a &lt;return&gt; block, the returned string is written directly into the response as XML.\n\n**NOTE:** The process of the web service is responsible for returning a valid string containing the XML as a result.\nIf no valid XML can be generated for the response with the result, an error response is delivered when the method is called.","ProcessDataModel.process":"The process itself, that is, the code to be executed when this process is called.\n\nAll JDito methods are available here to help you implement the desired process.\nGlobal functions can also be defined at this point (see e.g. `lib_keyword`).\n\nErrors in this process are displayed on the client if they were run at the client, otherwise they will not.","ProcessDataModel.loginTypeId":"Allows anonymous authentication for Web services processes.\n\nThis is where a login type is specified, which is specified in the instance config under `Client->Login` in the `loginList`.","ProcessDataModel.jditoWebserviceUser":"The title of the user used for executing JDito when the webservice is called. If specified, it will overwrite the login user.\nIf no value is provided and the webservice is accessed anonymously, no user will be available to the process.","ProcessDataModel.restrictedRoles":"For processes with Web services and login: Only users with the specified roles can run the WebService. If no roles are specified here, all of them are allowed to access this process.","ProcessDataModel.enableNestedRequests":"Determines whether nested resource requests are enabled or disabled for REST webservices.\nIt controls whether the RESTful web service application for this process allows nested resource requests.\n\n- If this property is set to `true`, nested resource requests will be accepted. In practice, this means URLs in the following formats would be valid:\n\t- `/my_process_ws/this/and/that/42/entries`\n\t- `/my_process_ws/orgs/reviewed/`\n\t- `/my_process_ws/`\n\nThe request URL is provided within the executing process.\n- If this property is set to `false`, nested resource requests will not be allowed, and a HTTP\n 404 error will be returned whenever nested resources are requested through this webservice.\n\nRegardless of this property's setting, non-nested requests are always possible. For example:\n- `/my_process_ws?param=value`\n- `/my_process_ws`","ProcessDataModel.serviceTaskParameterProcess":"Process to define the available parameters of the workflow service task.","ReportDataModel.alias":"The database alias that is used by this report.\nIn most cases this isn't necessary, because the alias property of the calling process or entity is used to gather the data.","ReportDataModel.reportData":"The data that is passed to a static report. These must be passed as a two-dimensional array.","ReportDataModel.subReports":"Possible sub-reports.","ReportDataModel.images":"Image data for the report.","ReportDataModel.iconInactive":"Inactive icon (inverse color to default icon for inactive display in frame tabs.)","ReportDataModel.grantExportProcess":"Process for the permission to export a record.\n\nReturns `result.string(true)` for \"allowed\", `result.string(false)` for \"not allowed\".","ReportDataModel.onHyperlink":"Process that is executed when a hyperlink is clicked.\n\nReturn value of the process `true` or `false`, `true` calls the browser as its own tab.\n\nError messages from this process do not arrive at the client, they are only visible in the server log.\nThe local variables are the individual parts of the entire URL","RoleDataModel.isAssignable":"Information if the role is assignable in the client","RoleDataModel.children":"list of other child roles","SystemDataModel.serverConfigPath":"Specifies the path to the server configuration file (`serverconfig.xml`).\nThis file can be created from the manager if it does not already exist.","SystemDataModel.tunnelConfigPath":"Specifies the path to the tunnel configuration file (`tunnelconfig.xml`)","SystemDataModel.productiveSystem":"If active, this system cannot be set as a standard system.\n\nIn addition, a security query must be confirmed when deploying.\nThis setting marks important systems that should not be accidentally deployed.","SystemDataModel.cloudSystemId":"Denotes the ID of the system in the SSP. If this property is set, the system is considered a cloud system.\nThis property is set by the system when checking out a system from the SSP and is not meant to be changed by the user.","SystemDataModel.signerLicense":"Signature license, i.e. license of the partner, which can customize ADITO.","SystemDataModel.aditoHomePath":"Path for the ADITO home directory that contains the program libraries.","SystemDataModel.aditoDataPath":"Path in which the ADITO application data (temp files, Lucene Index Search) are stored.","SystemDataModel.javaHomePath":"Base path of the Java Runtime environment. By default, `$ADITOHOME/jre/` is entered.","SystemDataModel.loginUser":"The user who logs in by default.","SystemDataModel.loginPassword":"Password of the user who logs in by default.","SystemDataModel.autoLogin":"If `true`, an automatic login is attempted when a `loginUser` is specified.","SystemDataModel.javaVMParametersServer":"Command line parameters (e.g. `-Dadito.debug`) for the server’s Java VM.","SystemDataModel.aditoDebug":"Sets the debug level of the outputs. Can also be specified via `-Dadito.debug`. Applies only when the server is started by the designer.\n\nFor `MAIL`: The file `aditomail.log` is created directly in the ADITO home directory and is not stored in the usual log directory.\n\nFor `DB`: Here the log file is stored in the same way as mail under the name `aditojdbc.log`.","SystemDataModel.enableJDitoDebug":"Enables the debugger.","SystemDataModel.javaVMParametersClient":"Command line parameters (e.g. `-Duser.timezone`) for the client's Java VM.","SystemDataModel.clientConfig":"Specifies the path to the client configuration file (`config.xml`).","SystemDataModel.serverAddress":"IP address for client requests. If you want the server address to be different from the designer when you start the client than in the preferences (`systemServerAddress`), it will be entered here.","SystemDataModel.serverPort":"Port that the client uses to connect to the server. If this property is not set, the port given in the instance configuration will be used.\nThis property is mandatory, if the server is behind a reverse proxy."}
